/* రాయ్ విద్యార్థి యాప్ – 2వ తరగతి పాఠ్యపుస్తకం పాఠాల నోట్స్ + టెస్ట్ ప్రశ్నలు + వర్క్‌బుక్ + టీచర్ గైడ్ (AP SCERT 2026-27, సెమిస్టర్-1) */
(window.RAAY_TB=window.RAAY_TB||{})[2]={"tel":[{"id":"te1","no":1,"t":"వాన","m":[8],"ty":"గేయం","th":"ప్రకృతి (దీర్ఘం ా)","by":"పాయల సత్యనారాయణ – తెలుగు లోగిలి – 2 (పుటలు 1–5)","sum":"వర్షం కురుస్తుంటే పిల్లలు కాలువలో కాగితం పడవలు వదులుతూ ఆనందంగా పాడే గేయం: “వానలు వానలు వానలు / పారే కొండా కోనలు / చిటపట కురిసే చినుకులు / మిలమిల మెరిసే మెరుపులు / పిల్లల పడవల నడకలు / మనసు నిండుగా వేడుకలు / బెకబెక అరిచే కప్పలు / కిలకిలలాడే చేపలు / వానలు వానలు వానలు / పారే కొండా కోనలు”. ఈ పాఠంలో దీర్ఘం (ా) గుణింతం – క→కా, వ→వా – తో వాన, తామర, కాకర, జామ, సాగరం, బంగారం వంటి పదాలు నేర్చుకుంటారు.","pts":["గేయం: వానలు వానలు వానలు / పారే కొండా కోనలు / చిటపట కురిసే చినుకులు / మిలమిల మెరిసే మెరుపులు / పిల్లల పడవల నడకలు / మనసు నిండుగా వేడుకలు / బెకబెక అరిచే కప్పలు / కిలకిలలాడే చేపలు","గేయ రచయిత: పాయల సత్యనారాయణ.","ధ్వన్యనుకరణ పదాలు: చిటపట (చినుకులు), మిలమిల (మెరుపులు), బెకబెక (కప్పలు), కిలకిల (చేపలు).","దీర్ఘం (ా): అకారానికి “ా” చేర్చితే దీర్ఘాక్షరం – క→కా, గ→గా, వ→వా, మ→మా. ఉదా: వాన = వా + న.","చిత్రాల పదాలు: కాకర, తామర, జామ, వంకాయ.","పదాలు: కాయ, తార, మామ, రామ, పాప; కారం, వారం, దారం, పావడా, కాగడా; సాగరం, వానరం, జాగారం, ఊరగాయ, ఆవకాయ; పాతాళం, గంగాళం, మందారం, బంగారం, వానాకాలం.","వాక్యాలు: పాట పాట ఏ పాట? పాట పాట వాన పాట. మాట మాట ఏ మాట? మాట మాట తాత మాట. హారం హారం ఏ హారం? హారం హారం ఫలహారం.","గబగబ పలకండి: వానలు వచ్చె – పంటలు పండె – రైతులు మెచ్చె.","పద్యం: వెలుగు రాకముందె వేగ నిదురలెమ్ము / ప్రొద్దు బొడవ నిదుర బోవరాదు / సోమరితనమేల శుచిశుభ్రముల యందు / తెలిసి నడచుకొమ్ము తెలుగుబిడ్డ! – భావం: తెల్లవారకముందే నిద్ర లేవాలి; ప్రొద్దు పొడిచాక నిద్రపోకూడదు; సోమరితనం వద్దు; శుచి, శుభ్రత పాటించాలి."],"w":[["వాన","వర్షం"],["కోనలు","లోయలు"],["చినుకులు","వాన బిందువులు"],["మెరుపులు","ఆకాశంలో కనిపించే కాంతి"],["వేడుకలు","సంబరాలు"],["సాగరం","సముద్రం"],["వానరం","కోతి"],["గంగాళం","పెద్ద పాత్ర"],["హారం","మాల"],["ఫలహారం","టిఫిన్"]],"gr":{"t":"దీర్ఘం (ా) గుణింతం","p":["అకారం: క గ చ జ ట డ ణ త ద న ప బ మ య ర ల వ శ ష స హ ళ","దీర్ఘం: కా గా చా జా టా డా ణా తా దా నా పా బా మా యా రా లా వా శా షా సా హా ళా","దీర్ఘం ఉన్న పదాలు: వాన, తామర, కాకర, జామ, సాగరం, మందారం, బంగారం.","ధ్వన్యనుకరణ: చిటపట, మిలమిల, బెకబెక, కిలకిల."]},"qa":[["చినుకులు ఎలా కురుస్తాయి?","చిటపట కురుస్తాయి."],["మెరుపులు ఎలా మెరుస్తాయి?","మిలమిల మెరుస్తాయి."],["కప్పలు ఎలా అరుస్తాయి?","బెకబెక అరుస్తాయి."],["వాన కురుస్తుంటే బయటకు వెళ్ళాలంటే ఏమి చేయాలి?","గొడుగు వేసుకోవాలి."],["వాన నీరు వృథా కాకుండా ఏం చేయాలి?","ఇంకుడు గుంతలు, డ్రమ్ముల్లో పట్టి మొక్కలకు వాడాలి."]],"act":"“వాన” గేయాన్ని అభినయిస్తూ పాడండి. చుక్కలు కలిపి జామకాయ బొమ్మ గీసి రంగులు వేయండి. దీర్ఘం (ా) ఉన్న పదాలు సేకరించండి.","kn":"వానలు పడితే పంటలు పండుతాయి, చెరువులు–బావులు నిండుతాయి. వానలు పడకపోతే కరువు, తాగునీటి కొరత వస్తుంది.","qz":[["“వాన” గేయ రచయిత","పాయల సత్యనారాయణ","గురజాడ అప్పారావు","జై సీతారాం","వేమన"],["“___ కురిసే చినుకులు”","చిటపట","మిలమిల","బెకబెక","కిలకిల"],["“మిలమిల మెరిసే ___”","మెరుపులు","చేపలు","కప్పలు","పడవలు"],["“బెకబెక అరిచే ___”","కప్పలు","చేపలు","పక్షులు","కుక్కలు"],["“కిలకిలలాడే ___”","చేపలు","కప్పలు","పడవలు","మెరుపులు"],["దీర్ఘం (ా) ఉన్న పదం","దారం","హంస","వడ","పడవ"],["ఎరుపు రంగులో ఉండే పువ్వు","మందారం","చామంతి","తామర","మల్లె"],["“క” కి దీర్ఘం చేరిస్తే","కా","కి","కు","కె"],["“వానరం” అంటే","కోతి","వాన","పక్షి","నది"],["వాన కురుస్తుంటే బయటకు వెళ్ళాలంటే","గొడుగు వేసుకోవాలి","పూలు కట్టాలి","మొక్కలు నాటాలి","ఆడుకోవాలి"],["“హారం హారం ఏ హారం? హారం హారం ___”","ఫలహారం","బంగారం","మందారం","గంగాళం"],["“వానలు వచ్చె – పంటలు పండె – ___ మెచ్చె”","రైతులు","పిల్లలు","పక్షులు","చేపలు"]],"tg":[["చిత్రం చూడండి (పుట 1)",["వర్షంలో పిల్లలు కాలువ దగ్గర కాగితం పడవలు వదులుతున్నారు; కుక్క, కప్పలు, చేపలు, తామరపూలు, ఉడత, సీతాకోకచిలుకలు ఉన్నాయి."]],["వినండి – మాట్లాడండి (పుట 2)",["ఆ) గొడుగు పట్టుకుంటాను / ఇంట్లో ఉంటాను / కాగితం పడవలు వదులుతాను.","ఇ) జలుబు, దగ్గు, జ్వరం వస్తాయి; పుస్తకాలు తడుస్తాయి.","ఈ) చిత్రం: తాతయ్య పెరటి తోటలో కూరగాయల మొక్కలకు నీళ్ళు పోస్తున్నారు; అమ్మ బిడ్డను ఎత్తుకుంది; పాప ఆకుకూరలు పట్టుకుంది; బుట్టల్లో గుమ్మడి, వంకాయలు, టమాటాలు, ముల్లంగి ఉన్నాయి."]],["చదవండి / రాయండి (పుటలు 2–4)",["అ) వానలు, నడక, పడవ, చిటపట – గేయంలో గుర్తించి సున్నా చుట్టాలి.","ఆ) వాన – “వా” కు సున్నా.","రాయండి అ) కా గా చా జా టా డా ణా తా దా నా పా • బా మా యా రా లా వా శా షా సా హా ళా","ఆ) దీర్ఘం పదాలు: తామర, వాన, కాకర, జామ, మామ, పాప, సాగరం, మందారం."]],["నేనేమి నేర్చుకున్నాను? (పుట 5)",["1) ఇ) దారం  2) మందారం  3) ఇ) మందారం","4) “గా” ఉన్న పదాలు: బంగారం, గంగాళం, ఊరగాయ","5) ఆ) గొడుగు వేసుకోవాలి","6) పట్టిక ఆధారంగా దీర్ఘాక్షర పదాలు: పాయసం (పా–య–సం), కారం (కా–రం), దారం (దా–రం)","7) ఇంకుడు గుంతలు తవ్వాలి; డ్రమ్ములు, తొట్లలో పట్టి మొక్కలకు, పనులకు వాడాలి; చెరువుల్లోకి మళ్ళించాలి."]]],"wb":{"pg":"2–6","f":"books/2/Class2_Workbook_Sem1.pdf","p":8,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"తలకట్టు (క) – దీర్ఘం (కా) తేడా గమనించాలి: దయ–దారం, పదం–పాదం. దీర్ఘం మొదటి అక్షరానికే చేర్చాలి: రమ → రామ.","qz":[["దీర్ఘం (ా) ఉన్న అక్షరం","తా","క","ప","ల"],["“పప” కి సరైన పదం","పాప","పప","పపా","పోప"],["వేరుగా ఉన్న గుణింత పదం","శాతం","బలపం","పలక","మరక"],["తలుపుకు వేసేది","తాళం","గాలం","హారం","దారం"],["మా పెరటిలో ___ పూసింది","మందారం","జామ","కాకర","వంకాయ"],["___ కాయ తీయగా ఉంటుంది","జామ","కాకర","వేప","మిరప"],["మామ కాని మామ ఎవరు?","చందమామ","రాజామామ","మా మామ","అమ్మమామ"],["హారం – మొదటి అక్షరం","హా","హ","రం","ర"],["మం __ రం (మందారం)","దా","తా","కా","మా"],["వం __ య (వంకాయ)","కా","మా","తా","దా"],["ఆ కాయ ___ కాయ (చేదుగా ఉండేది)","కాకర","జామ","మామిడి","అరటి"],["రమ, జమ, పలు – మొదటి అక్షరానికి దీర్ఘం","రామ, జామ, పాలు","రామ, జామా, పలు","రమ, జామ, పాలు","రామా, జమ, పాలు"]]}},{"id":"te2","no":2,"t":"చిలకల్లారా చిలకల్లారా!","m":[8],"ty":"గేయం","th":"పక్షులు (గుడి ి, గుడి దీర్ఘం ీ)","by":"గురజాడ అప్పారావు – తెలుగు లోగిలి – 2 (పుటలు 6–10)","sum":"చెట్లు చిలకలతో మాట్లాడే గేయం: “చింత చెట్టు చిలకల తోటి ఏమని పలికింది? చిలకల్లారా చిలకల్లారా వద్దూ వద్దంది / కొబ్బరి చెట్టు చిలకల తోటి ఏమని పలికింది? చిలకల్లారా చిలకల్లారా వద్దూ వద్దంది / జామ చెట్టు చిలకల తోటి ఏమని పలికింది? చిలకల్లారా చిలకల్లారా రండీ రండంది / మామిడి చెట్టు చిలకల తోటి ఏమని పలికింది? చిలకల్లారా చిలకల్లారా రండీ రండంది”. గుడి (ి), గుడి దీర్ఘం (ీ) గుణింతాలు – చిలక, చీమ, కిటికీ, బీరకాయ, సీతాఫలం.","pts":["గేయం: చింత చెట్టు, కొబ్బరి చెట్టు – “వద్దూ వద్దంది”; జామ చెట్టు, మామిడి చెట్టు – “రండీ రండంది” (చిలకలకు ఇష్టమైన పండ్లు ఇచ్చే చెట్లు).","గేయ రచయిత: గురజాడ అప్పారావు.","చిత్రకథ: గీతాంజలి రాజు వాళ్ళ పొలానికి వెళ్ళింది. మొక్కజొన్న కంకులపై పిచ్చుకలు వాలి తినడం చూసి సంతోషించింది. చుట్టూ ఎగురుతున్న తూనీగలను చూసి ఆనందించింది. సరదాగా గడిపి ఇంటికి చేరింది.","గుడి (ి): కి గి చి జి టి… ; గుడి దీర్ఘం (ీ): కీ గీ చీ జీ టీ…","పదాలు: గిరి, హరి, నది, గది; కంకి, బండి, సంచి, అంజి; గీత, సీత, పీపా, సీసా; తీరం, గీతం, దీపం, జీతం; గిలక, చిలక, కిరాయి, సిపాయి; వినికిడి, పిడికిలి, సీతాఫలం, శీతాకాలం.","చిత్రాలు–పదాలు: కిటికీ, మీసం, బీరకాయ, కాకి.","వాక్యాలు: ఈగ మిఠాయి చూసింది. చీమను పిలిచింది. ఈగ, చీమ కలిసి మిఠాయి తిని ఆనందించాయి.","గబగబ పలకండి: చెట్టు తొర్రలో బుర్రు పిట్ట నిద్రపోయె.","పద్యం: వెలుగు రాకముందె వేగ నిదురలెమ్ము / ప్రొద్దు బొడవ నిదుర బోవరాదు / సోమరితనమేల శుచిశుభ్రముల యందు / తెలిసి నడచుకొమ్ము తెలుగుబిడ్డ! – భావం: తెల్లవారకముందే నిద్ర లేవాలి; ప్రొద్దు పొడిచాక నిద్రపోకూడదు; సోమరితనం వద్దు; శుచి, శుభ్రత పాటించాలి."],"w":[["చిలక","చిలుక"],["పలికింది","అన్నది"],["కంకి","కంకి (మొక్కజొన్న/జొన్న వెన్ను)"],["తూనీగ","తూనీగ పురుగు"],["గిలక","బావిలో నీరు తోడే చక్రం"],["కిరాయి","అద్దె"],["సిపాయి","సైనికుడు"],["వినికిడి","వినే శక్తి"],["శీతాకాలం","చలికాలం"],["తొర్ర","చెట్టు కాండంలోని రంధ్రం"]],"gr":{"t":"గుడి (ి), గుడి దీర్ఘం (ీ)","p":["గుడి: కి గి చి జి టి డి ణి తి ది ని పి బి మి యి రి లి వి శి షి సి హి ళి","గుడి దీర్ఘం: కీ గీ చీ జీ టీ డీ ణీ తీ దీ నీ పీ బీ మీ యీ రీ లీ వీ శీ షీ సీ హీ ళీ","గుడి పదాలు: చిలక, కిటికీ (కి), పిడికిలి; గుడి దీర్ఘం పదాలు: చీమ, మీసం, బీరకాయ, సీతాఫలం.","పూర్తిగా గుడి ఉన్న పదం: పిడికిలి (పి–డి–కి–లి)."]},"qa":[["చింత చెట్టు చిలకలతో ఏమంది?","వద్దూ వద్దంది."],["జామ చెట్టు చిలకలతో ఏమంది?","రండీ రండంది."],["చిలక ముక్కు ఏ రంగులో ఉంటుంది?","ఎరుపు రంగులో."],["గీతాంజలి ఎవరి పొలానికి వెళ్ళింది?","రాజు వాళ్ళ పొలానికి."],["వేసవిలో పక్షులకు నీళ్ళు ఎందుకు పెట్టాలి?","ఎండలకు నీరు దొరకక పక్షులు దాహంతో బాధపడతాయి."]],"act":"గేయాన్ని అభినయిస్తూ పాడండి. చుక్కలు కలిపి మామిడికాయ బొమ్మ గీసి రంగు వేయండి. పక్షులు, వాటి నివాసాల (గూళ్ళ) గురించి తెలుసుకోండి.","kn":"చిలకలు జామ, మామిడి పండ్లు ఇష్టంగా తింటాయి. పక్షుల నివాసాలు: చిలుక – చెట్టు తొర్ర, గిజిగాడు – అల్లిన గూడు, కాకి – పుల్లల గూడు.","qz":[["“చిలకల్లారా” గేయ రచయిత","గురజాడ అప్పారావు","పాయల సత్యనారాయణ","న్యాయపతి రాఘవరావు","వేమన"],["చింత చెట్టు చిలకలతో","వద్దూ వద్దంది","రండీ రండంది","పాడండి అంది","ఆడండి అంది"],["మామిడి చెట్టు చిలకలతో","రండీ రండంది","వద్దూ వద్దంది","వెళ్ళండి అంది","ఏమీ అనలేదు"],["గీతాంజలి ఎవరి పొలానికి వెళ్ళింది?","రాజు","రాము","మామయ్య","తాతయ్య"],["మొక్కజొన్న కంకులపై వాలిన పక్షులు","పిచ్చుకలు","చిలకలు","కాకులు","పావురాలు"],["గీతాంజలి ఆనందించినది","ఎగురుతున్న తూనీగలను చూసి","ఈగలను చూసి","దోమలను చూసి","చేపలను చూసి"],["గుడి దీర్ఘం (ీ) ఉన్న పదం","చీమ","చిలక","గిరి","నది"],["పూర్తిగా గుడి (ి) అక్షరాలున్న పదం","పిడికిలి","బావి గిలక","సిపాయి","సీతాఫలం"],["__లక (చిలక)","చి","నే","జీ","కా"],["క, కా, __, కీ","కి","కు","కె","కొ"],["ధర__, మిఠా__","ణి, యి","ని, ఈ","తి, రి","డి, లి"],["సీతాఫలం ఏమిటి?","పండు","కూరగాయ","పక్షి","పువ్వు"]],"tg":[["చిత్రం చూడండి (పుట 6)",["పిల్లలు చింత, కొబ్బరి, జామ, మామిడి చెట్లపై చిలకలను చూపిస్తూ ఆనందంగా పాడుతున్నారు; చెట్టు కింద చీమ ఉంది."]],["వినండి – మాట్లాడండి (పుట 7)",["ఆ) ఎరుపు రంగులో.","ఇ) మామిడి, జామ, వేప, చింత, కొబ్బరి, మర్రి, రావి, తాటి.","ఈ) 1. ఆ) రాజు  2. అ) పిచ్చుకలు  3. ఇ) ఎగురుతున్న తూనీగలు"]],["చదవండి (పుటలు 7–8)",["ఆ) చిలక – “చి”, చీమ – “చీ” కు సున్నా.","ఈ) జతపరచడం: కిటికీ – కిటికీ బొమ్మ, మీసం – మీసం బొమ్మ, బీరకాయ – బీరకాయ బొమ్మ, కాకి – కాకి బొమ్మ."]],["రాయండి (పుట 9)",["గుడి: కి గి చి జి టి డి ణి తి ది ని పి • బి మి యి రి లి వి శి షి సి హి ళి","గుడి దీర్ఘం: కీ గీ చీ జీ టీ డీ ణీ తీ దీ నీ పీ • బీ మీ యీ రీ లీ వీ శీ షీ సీ హీ ళీ","ఆ) కాకి, చీమ, చిలక, గీత, దీపం, సీసా, మీసం, కిటికీ"]],["నేనేమి నేర్చుకున్నాను? (పుట 10)",["1) అ) చి  2) సీతాఫలం  3) ఆ) పిడికిలి  4) కి  5) ఇ) ణి, యి","6) పండు – సీతాఫలం, కూరగాయ – బీరకాయ, పక్షి – చిలక/కాకి","7) వేసవిలో నీటి వనరులు ఎండిపోతాయి; పక్షులు దాహంతో చనిపోకుండా మట్టి గిన్నెల్లో నీళ్ళు పెట్టాలి."]]],"wb":{"pg":"7–11","f":"books/2/Class2_Workbook_Sem1.pdf","p":13,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"గుడి (ి) – కి, గుడి దీర్ఘం (ీ) – కీ తేడా: చిలక (చి), చీమ (చీ). గతం → గీతం (గుడి దీర్ఘం).","qz":[["గుడి (ి) అక్షరం","కి","కీ","కా","క"],["గుడి దీర్ఘం (ీ) అక్షరం","చీ","చి","చా","చ"],["కిటికీ బొమ్మకు సరైన పదం","కిటికీ","కటికి","కటికీ","కిటకి"],["గుడి అక్షరం ఉన్న పండు","ఉసిరి","మామిడి","సపోటా","అరటి"],["వేరుగా ఉన్న పదం","గిలక","తాత","మామ","పాప"],["అడవికి రాజు","సింహం","చింపాంజీ","జిరాఫీ","ఏనుగు"],["__తాఫలం","సీ","సి","సా","సు"],["మి __ ద (మిడత)","డ","ద","త","ట"],["ఈ కలం ఎవరిది? – ఈ కలం ___ ది","సీత","శివ","వినీత","గీత"],["తోక ఉంది కానీ జంతువును కాను, నూనె తాగుతాను – ఎవరిని?","దీపం","ఎలుక","కోతి","గాలిపటం"],["గతం – మొదటి అక్షరానికి గుడి దీర్ఘం","గీతం","గాతం","గితం","గూతం"],["బీర + కాయ =","బీరకాయ","బిరకాయ","బీరాకాయ","బేరకాయ"]]}},{"id":"te3","no":3,"t":"పూచిన పూలు","m":[8],"ty":"గేయం","th":"పూలు (కొమ్ము ు, కొమ్ము దీర్ఘం ూ, ఋత్వం ృ)","by":"న్యాయపతి రాఘవరావు – తెలుగు లోగిలి – 2 (పుటలు 11–15)","sum":"పూలు పిల్లలను పిలుస్తున్న గేయం: “పూచిన పూలూ ఏమన్నాయి? విచ్చిన పూలూ ఏమన్నాయి? పిల్లల్లారా రమ్మన్నాయి! చిన్ని కృష్ణునికి ఇమ్మన్నాయి! / రోజా పూలూ ఏమన్నాయి? జాజీ పూలూ ఏమన్నాయి? ధృతికీ కృతికీ ఇమ్మన్నాయి! పూలదండలు గుచ్చమన్నాయి! / బంతిపూలు ఏమన్నాయి? చామంతి పూలూ ఏమన్నాయి? బంతులాటా ఆడమన్నాయి! గంతులు వేస్తూ పాడమన్నాయి!”. కొమ్ము (ు), కొమ్ము దీర్ఘం (ూ), ఋత్వం (ృ) గుణింతాలు – గుడి, పూలు, గృహం, వృక్షం.","pts":["గేయ రచయిత: న్యాయపతి రాఘవరావు.","పూచిన/విచ్చిన పూలు → పిల్లలను రమ్మన్నాయి, చిన్ని కృష్ణునికి ఇమ్మన్నాయి. రోజా, జాజి పూలు → ధృతికీ కృతికీ ఇమ్మన్నాయి, పూలదండలు గుచ్చమన్నాయి. బంతి, చామంతి పూలు → బంతులాట ఆడమన్నాయి, గంతులు వేస్తూ పాడమన్నాయి.","కొమ్ము (ు): కు గు చు …; కొమ్ము దీర్ఘం (ూ): కూ గూ చూ …; ఋత్వం (ృ): కృ గృ …","చిత్రాలు: బుడగ, సూది, వృక్షం, తూనీగ.","పదాలు: కుడి, గుడి, ముడి, రాజు, గాజు; సుఖం, ముఖం; సూది, దూది, కూర, బూర; పూలు, నూలు, జూలు, గూడు; తలుపు, నలుపు, మలుపు, కూడిక, పూడిక; శృతి, కృతి, ధృతి, ఆకృతి, జాగృతి.","వాక్యాలు: మామిడి చిగురు వేసింది. మామిడి పూత పూసింది. మామిడికాయ కాసింది. మామిడి పండు పండింది.","గబగబ పలకండి: గులాబీ పువ్వులు పూసెను. పాపాయి నవ్వులు విరిసెను.","పద్యం: బడికి వెళ్ళుటకును గొడవ చేయగరాదు / తల్లిదండ్రి మాట తప్పరాదు / పెద్దవారి మాట పెన్నిధి సమమౌను / తెలిసి మెలగ మేలు తెలుగు బాల! – భావం: బడికి వెళ్ళడానికి గొడవ చేయకూడదు; తల్లిదండ్రుల మాట జవదాటకూడదు; పెద్దల మాట గొప్ప నిధి లాంటిది."],"w":[["పూచిన","పుష్పించిన"],["విచ్చిన","వికసించిన"],["గుచ్చు","దారంలో కూర్చు"],["గంతులు","ఎగురుళ్ళు"],["గృహం","ఇల్లు"],["వృక్షం","చెట్టు"],["దూది","పత్తి"],["నూలు","దారం"],["జూలు","సింహం మెడ వెంట్రుకలు"],["చిగురు","లేత ఆకు"]],"gr":{"t":"కొమ్ము (ు), కొమ్ము దీర్ఘం (ూ), ఋత్వం (ృ)","p":["కొమ్ము: కు గు చు జు టు డు ణు తు దు ను పు బు ము యు రు లు వు శు షు సు హు ళు","కొమ్ము దీర్ఘం: కూ గూ చూ జూ టూ డూ ణూ తూ దూ నూ పూ బూ మూ …","ఋత్వం: కృ గృ చృ జృ టృ డృ ణృ తృ దృ నృ పృ బృ మృ వృ శృ సృ హృ","ఉదా: గుడి (కొమ్ము), పూలు (కొమ్ము దీర్ఘం), గృహం, వృక్షం, కృషి (ఋత్వం)."]},"qa":[["పూచిన పూలు పిల్లలతో ఏమన్నాయి?","రమ్మన్నాయి."],["రోజా, జాజి పూలు ఎవరికి ఇమ్మన్నాయి?","ధృతికీ కృతికీ."],["బంతిపూలు ఏమన్నాయి?","బంతులాట ఆడమన్నాయి."],["పూలతో ఏమి చేస్తారు?","దండలు కడతారు, దేవునికి పూజ చేస్తారు, జడలో పెట్టుకుంటారు, అలంకరిస్తారు."],["పూల మొక్కలు తుంచేస్తే ఏమనిపిస్తుంది?","బాధగా ఉంటుంది; మొక్కలకూ ప్రాణం ఉంది."]],"act":"గేయాన్ని అభినయిస్తూ పాడండి. రంగు కాగితాలతో పువ్వు తయారు చేయండి. మీకు తెలిసిన పూల పేర్లు చెప్పండి. పూలతో ఏమేమి తయారు చేస్తారో తెలుసుకోండి.","kn":"పూలతో దండలు, అత్తరు (సెంట్), గులాబీ నీరు (పన్నీరు), గుల్కండ్ తయారు చేస్తారు; పెళ్ళిళ్ళు, పండుగలు, పూజల్లో అలంకరణకు వాడతారు.","qz":[["“పూచిన పూలు” గేయ రచయిత","న్యాయపతి రాఘవరావు","గురజాడ అప్పారావు","జై సీతారాం","పాయల సత్యనారాయణ"],["పూచిన పూలు పిల్లలను","రమ్మన్నాయి","పొమ్మన్నాయి","ఆడమన్నాయి","చదవమన్నాయి"],["పూలు ఎవరికి ఇమ్మన్నాయి?","చిన్ని కృష్ణునికి","రామునికి","అమ్మకు","టీచర్‌కు"],["“ధృతికీ కృతికీ ఇమ్మన్నాయి” అన్న పూలు","రోజా, జాజి","బంతి, చామంతి","మల్లె, మొల్ల","తామర, కలువ"],["బంతిపూలు ఏమన్నాయి?","బంతులాట ఆడమన్నాయి","దండలు గుచ్చమన్నాయి","రమ్మన్నాయి","పొమ్మన్నాయి"],["తూనీగ ఏ అక్షరంతో మొదలవుతుంది?","తూ","తు","తే","తా"],["ఋత్వం (ృ) తో మొదలయ్యే పదం","వృక్షం","కుడి","సూది","పూలు"],["“మహా___”","వృక్షం","జూలు","రూపాయి","గూడు"],["కొమ్ము దీర్ఘం (ూ) ఉన్న పదం","సూది","గుడి","కృతి","గృహం"],["సరైన వాక్యం","మామిడి పూత పూసింది","కావాలి పూజితకు పూతరేకులు","తేలిక దూది బరువు","చెట్టు ఎగిరింది"],["“గృహం” అంటే","ఇల్లు","చెట్టు","పువ్వు","గుడి"],["దండల తయారీకి వాడే పూలు","బంతి, చామంతి","కాకర, బీర","మామిడి, జామ","వరి, గోధుమ"]],"tg":[["చిత్రం చూడండి (పుట 11)",["చిన్ని కృష్ణుడు వేణువు ఊదుతూ కూర్చున్నాడు; అమ్మాయిలు (కృతి, ధృతి) పూలు, పూలమాలలు, పూలబంతితో కృష్ణుని చుట్టూ ఆడుకుంటున్నారు."]],["వినండి – మాట్లాడండి (పుట 12)",["ఆ) పూలతో దండలు కడతాము, దేవునికి పూజ చేస్తాము, జడలో పెట్టుకుంటాము.","ఇ) మల్లె, గులాబీ, బంతి, చామంతి, మందారం, కనకాంబరం, తామర, సంపంగి, జాజి.","ఈ) చిత్రం: పూల దుకాణంలో దంపతులు పూలమాలలు కడుతున్నారు; ఒక పాప పూలు కొంటోంది; పూల కుండీలు, దండలు వేలాడుతున్నాయి."]],["చదవండి / రాయండి (పుటలు 12–14)",["ఆ) గుడి – “గు”, పూలు – “పూ”, గృహం – “గృ” కు సున్నా.","రాయండి: కు గు చు జు టు డు ణు తు దు ను పు / కూ గూ చూ … / కృ గృ చృ …; ఆ) గుడి, కూతురు, కృషి, పులి, సూది, వృక్షం, మృగం, పూలు"]],["నేనేమి నేర్చుకున్నాను? (పుట 15)",["1) ఇ) తూ  2) వృక్షం  3) అ) వృక్షం (మహావృక్షం)","4) కొమ్ము: గుడి, తులం • కొమ్ము దీర్ఘం: కూడిక, సూది • ఋత్వం: బృందం, మృగం","5) ఆ) మామిడి పూత పూసింది.  6) బంతి, చామంతి (మల్లె, కనకాంబరం)","7) బాధగా ఉంటుంది; మొక్కలకూ ప్రాణం ఉంది – పూలను అనవసరంగా తుంచకూడదు."]]],"wb":{"pg":"12–16","f":"books/2/Class2_Workbook_Sem1.pdf","p":18,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"కొమ్ము (ు) – గు, కొమ్ము దీర్ఘం (ూ) – గూ, ఋత్వం (ృ) – గృ తేడా గుర్తించాలి. గృహప్రవేశం (గృ) – గుహప్రవేశం తప్పు.","qz":[["పక్షి నివాసం","గూడు","గృహం","దాబా","గుడి"],["ఋత్వం (ృ) ఉన్న పదం","గృహం","గుడి","గూడు","గుర్రం"],["కొమ్ము దీర్ఘం (ూ) ఉన్న పదం","తూనీగ","తులం","తిలకం","తాళం"],["మూడు – మొదటి అక్షరం","మూ","ము","మృ","మా"],["__ క్షం (చెట్టు)","వృ","వు","వూ","వ"],["__ దగ (బుడగ)","బు","బూ","బృ","బ"],["గృహం అంటే","ఇల్లు","గుడి","చెట్టు","పువ్వు"],["ఐదు ___ పండ్లు (చిత్రం)","మామిడి","అరటి","చెర్రీ","జామ"],["సుజాతకు గులాబి పూలు ___","కావాలి","వద్దు","ఉన్నాయి","లేవు"],["పైనొక పలక – కిందొక పలక, పలకల నడుమ మెలికల గిలక – ఏమిటి?","నాలుక","పళ్ళు","చెవి","కన్ను"],["అర్థవంతమైన వాక్యం","ఈ రోజు మా గృహప్రవేశం","ఈ రోజు మా గుహప్రవేశం","ఈ రోజు మా గహప్రవేశం","ఈ రోజు మా గూహప్రవేశం"],["ఆకుకూరలు తినడం ___","మంచిది","చెడ్డది","కష్టం","వద్దు"]]}},{"id":"te4","no":4,"t":"పరుగు పందెం","m":[9],"ty":"గేయ కథ","th":"నీతి (ఎత్వం ె, ఏత్వం ే)","by":"జై సీతారాం – తెలుగు లోగిలి – 2 (పుటలు 16–20)","sum":"కుందేలు–తాబేలు పరుగు పందెం గేయ కథ: “కుందేలు తాబేలు పందెమేసుకున్నాయి / చెరువు నుండి కొండదాక పరుగెత్తే పందెము! / కుందేలు చెంగు చెంగున ముందు ముందుకు పోయింది / దారిలోన చల్లనైన చెట్టు నీడన చేరింది! / కళ్ళుమూసి పడుకుంది గాఢ నిద్ర పోయింది / నిముషమైన తాబేలు నిలవకుండా నడిచింది! / కాసేపటికి కుందేలు మేలుకొని చూసింది / ఇంకేముంది ఇంకేముంది తాబేలే గెలిచింది!”. ఎత్వం (ె), ఏత్వం (ే) గుణింతాలు – చెరువు, తాబేలు, జెండా, తేలు, నెమలి, గేదె.","pts":["గేయ రచయిత: జై సీతారాం.","కథ: పందెం చెరువు నుండి కొండ దాకా. కుందేలు చెంగు చెంగున ముందుకు పోయి చెట్టు నీడలో నిద్రపోయింది. తాబేలు ఒక్క నిమిషం కూడా ఆగకుండా నడిచి గెలిచింది.","నీతి: పోటీలో అలసత్వం (సోమరితనం) ఉండకూడదు; నిదానంగా అయినా నిరంతరం శ్రమిస్తే గెలుపు తప్పదు.","చిత్రకథ: బేతాళపురంలో ఐదుగురు స్నేహితులు; ఊరి చివర రెండు పెద్ద చెట్లు; సెలవు రోజుల్లో గోనె సంచులు కాళ్ళకు తొడుక్కుని పరుగు పందెం; వారి ఐకమత్యాన్ని పెద్దలు మెచ్చుకున్నారు.","ఎత్వం (ె): కె గె చె …; ఏత్వం (ే): కే గే చే …","పదాలు: గెల, నెల, వెల, మెడ, గెడ; తేలు, మేలు, వేలు, రేఖ, లేఖ; చేప, వేప, నేత, మేత, లేత; గెలుపు, తెలుపు, మెరుపు, తెలుగు, వెలుగు; నేరేడు, మారేడు, తేనీరు, చేపలు; కేశం, దేశం, వేణువు, వేషం, మేఘం.","గబగబ పలకండి: గురిపెట్టి పరుగెత్తి బహుమతిని పట్టు.","పద్యం: బడికి వెళ్ళుటకును గొడవ చేయగరాదు / తల్లిదండ్రి మాట తప్పరాదు / పెద్దవారి మాట పెన్నిధి సమమౌను / తెలిసి మెలగ మేలు తెలుగు బాల! – భావం: బడికి వెళ్ళడానికి గొడవ చేయకూడదు; తల్లిదండ్రుల మాట జవదాటకూడదు; పెద్దల మాట గొప్ప నిధి లాంటిది."],"w":[["పందెం","పోటీ"],["చెంగు చెంగున","గెంతుతూ"],["గాఢ నిద్ర","గట్టి నిద్ర"],["నిముషమైన","ఒక్క నిమిషం కూడా"],["మేలుకొని","నిద్ర లేచి"],["గెల","అరటి గెల"],["మేత","పశువుల ఆహారం"],["కేశం","వెంట్రుక"],["మేఘం","మబ్బు"],["ఐకమత్యం","కలిసి ఉండటం"]],"gr":{"t":"ఎత్వం (ె), ఏత్వం (ే)","p":["ఎత్వం: కె గె చె జె టె డె ణె తె దె నె పె బె మె యె రె లె వె శె షె సె హె ళె","ఏత్వం: కే గే చే జే టే డే ణే తే దే నే పే బే మే యే రే లే వే శే షే సే హే ళే","ఎత్వం పదాలు: చెరువు, నెమలి, జెండా, తెలుపు; ఏత్వం పదాలు: తాబేలు, తేలు, గేదె, చేప, మేఘం.","ఏత్వంతో మొదలయ్యే జత: చేపలు, నేరేడు."]},"qa":[["పందెం ఎక్కడి నుండి ఎక్కడి దాకా?","చెరువు నుండి కొండ దాకా."],["కుందేలు ఎక్కడ నిద్రపోయింది?","దారిలో చల్లని చెట్టు నీడలో."],["పందెంలో ఎవరు గెలిచారు?","తాబేలు."],["కుందేలు ఎందుకు ఓడిపోయింది?","గర్వంతో, అలసత్వంతో మధ్యలో నిద్రపోయింది."],["ఈ కథ నేర్పే నీతి ఏమిటి?","పోటీలో అలసత్వం ఉండకూడదు; నిదానమే ప్రధానం."]],"act":"గేయ కథను సొంత మాటల్లో చెప్పండి. ఆకులను చేప ఆకారంలో అతికించి పేరు రాయండి. గోనె సంచుల పరుగు పందెం ఆడండి.","kn":"ఇంటి లోపల ఆటలు: చదరంగం, క్యారమ్స్, వైకుంఠపాళి, అష్టాచెమ్మా. బయటి ఆటలు: కబడ్డీ, ఖో-ఖో, తొక్కుడు బిళ్ళ, పరుగు పందెం. ఆటలతో ఆరోగ్యం, స్నేహం, ఉత్సాహం.","qz":[["“పరుగు పందెం” గేయ రచయిత","జై సీతారాం","గురజాడ అప్పారావు","కస్తూరి నరసింహమూర్తి","వేమన"],["పందెం ఎక్కడి నుండి ఎక్కడి దాకా?","చెరువు నుండి కొండ దాకా","ఇంటి నుండి బడి దాకా","కొండ నుండి నది దాకా","ఊరి నుండి అడవి దాకా"],["కుందేలు ఎక్కడ నిద్రపోయింది?","చెట్టు నీడలో","చెరువు దగ్గర","కొండ మీద","ఇంట్లో"],["పందెంలో గెలిచింది","తాబేలు","కుందేలు","రెండూ","ఏదీ కాదు"],["బేతాళపురంలో స్నేహితులు ఎంతమంది?","ఐదుగురు","ఇద్దరు","ముగ్గురు","పదిమంది"],["ఊరి చివర పెద్ద చెట్లు ఎన్ని?","రెండు","ఒకటి","మూడు","నాలుగు"],["స్నేహితులకు ఇష్టమైన ఆట","గోనె సంచులతో పరుగు పందెం","దాగుడు మూతలు","బంతాట","క్రికెట్"],["ఏత్వం (ే) తో మొదలయ్యే పదాల జత","చేపలు, నేరేడు","తేలు, తాబేలు","జిలేబి, పేలాలు","నెల, గెల"],["నేల మీద నిదానం, నీటిలో బహువేగం – ఎవరు?","తాబేలు","చేప","కుందేలు","కప్ప"],["కథ నీతి","పోటీలో అలసత్వం ఉండకూడదు","కునుకు తీసేవారు గెలుస్తారు","కుందేలు, తాబేలు సమానం","వేగమే ముఖ్యం"],["“తె” తో మొదలయ్యే రంగు","తెలుపు","నలుపు","ఎరుపు","పసుపు"],["“తె” తో మొదలయ్యే భాష","తెలుగు","తమిళం","హిందీ","కన్నడ"]],"tg":[["చిత్రం చూడండి (పుట 16)",["కుందేలు–తాబేలు పరుగు పందెం దృశ్యాలు: మొదలు, కుందేలు చెట్టు నీడలో నిద్ర, తాబేలు నడక, తాబేలు గెలుపు."]],["వినండి – మాట్లాడండి (పుట 17)",["అ) కథ సొంత మాటల్లో (పై సారాంశం).","ఆ) గర్వంతో, సోమరితనంతో మధ్యలో నిద్రపోవడం వల్ల.","ఇ) “పరుగు పందెం వేసుకుందాం – చెరువు నుండి కొండ దాకా” అని మాట్లాడుకున్నాయి.","ఈ) 1. ఆ) బేతాళపురం  2. ఆ) రెండు  3. ఇ) గోనె సంచులతో పరుగు పందెం"]],["చదవండి (పుటలు 17–18)",["ఆ) చెరువు – “చె”, తాబేలు – “బే” కు సున్నా.","ఈ) జతపరచడం: జెండా, నెమలి, గేదె, తేలు – బొమ్మలతో.","ఊ) 1. పరుగు పందెం  2. కుందేలు  3. తాబేలు"]],["రాయండి (పుట 19)",["ఎత్వం: కె గె చె జె టె డె ణె తె దె నె పె / బె మె యె రె లె వె శె షె సె హె ళె","ఏత్వం: కే గే చే జే టే డే ణే తే దే నే పే / బే మే యే రే లే వే శే షే సే హే ళే","ఆ) నెల, తేలు, చేప, వేప, మెడ, గేదె, జెండా, మేఘం"]],["నేనేమి నేర్చుకున్నాను? (పుట 20)",["1) ఇ) చేపలు, నేరేడు  2) నెమలి  3) అ) తాబేలు","4) ఎత్వం: చెరకు • ఏత్వం: దేవుడు, మారేడు","5) అ) పోటీలో అలసత్వం ఉండకూడదు.  6) రంగు – తెలుపు, భాష – తెలుగు","7) ఓడిన స్నేహితులను ఓదార్చి, మెచ్చుకుంటాను; గర్వపడను; కలిసి ఆడుకుంటాను."]]],"wb":{"pg":"17–21","f":"books/2/Class2_Workbook_Sem1.pdf","p":23,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"ఎత్వం (ె) – కె, ఏత్వం (ే) – కే తేడా: నెమలి (నె), తేలు (తే). వాక్యంలో పదాల క్రమం సరిగా ఉండాలి.","qz":[["తాబేలు బొమ్మకు సరైన పదం","తాబేలు","చేప","తిమింగలం","తేలు"],["ఎత్వం (ె) తో మొదలయ్యే చిత్రం","నెమలి","గద్ద","తేలు","చేప"],["స్వాతంత్ర్య దినోత్సవం రోజున ___ ఎగురవేస్తాము","జెండా","గాలిపటం","బెలూన్","పక్షి"],["కాకరకాయ ___గా ఉంటుంది","చేదు","తీపి","పులుపు","కారం"],["ఇది ___ మంచం","టేకు","నేరేడు","జిలేబి","చేదు"],["___ తీయగా ఉంటుంది","జిలేబి","చేదు","టేకు","రెండవ"],["కుం __ లు (కుందేలు)","దే","దె","డే","దా"],["__ రేడు (నేరేడు)","నే","నె","నా","ని"],["“సహజం ఓటములు గెలుపు” సరిచేస్తే","గెలుపు ఓటములు సహజం","ఓటములు గెలుపుకు సహజం కాదు","సహజం గెలుపు ఓటమి లేదు","గెలుపే సహజం"],["ఎడారి ఓడను నేను – ఎవరిని?","ఒంటె","ఏనుగు","గుర్రం","నౌక"],["అరటి ___","గెల","జెండా","వేలు","పూత"],["జాతీయ ___","జెండా","గెల","చెరువు","వేప"]]}},{"id":"te5","no":5,"t":"కొంటె కోతి","m":[9],"ty":"గేయం","th":"జంతువులు (ఒత్వం ొ, ఓత్వం ో)","by":"కస్తూరి నరసింహమూర్తి – తెలుగు లోగిలి – 2 (పుటలు 21–25)","sum":"కోతి బావ అల్లరిని వర్ణించే గేయం: “కోతిబావ నీకు కాస్త కోపమెక్కువ / కొంటెపనులు అంటే నీకు కోరికెక్కువ / పిందెలన్ని తుంచిపెట్ట ప్రీతి ఎక్కువ / కొబ్బరంటె చాలు నీకు ఇష్టమెక్కువ / రొట్టెముక్క చూస్తేనేమొ లొట్టలెక్కువ / దుకాణాలు చూస్తే నీకు దూకుడెక్కువ / గుణములన్ని ఎంచి చూడ కుదురు తక్కువ / గుడి గోపురమెక్కితే గంతు లెక్కువ”. ఒత్వం (ొ), ఓత్వం (ో) గుణింతాలు – గొడుగు, కోతి, కొడవలి, బొంగరం, కోడి, టోపి.","pts":["గేయ రచయిత: కస్తూరి నరసింహమూర్తి.","కోతి బావకు ఎక్కువైనవి: కోపం, కొంటెపనుల కోరిక, పిందెలు తుంచే ప్రీతి, కొబ్బరి ఇష్టం, రొట్టెముక్కకు లొట్టలు, దుకాణాలపై దూకుడు, గుడి గోపురంపై గంతులు; తక్కువైనది: కుదురు.","ఒత్వం (ొ): కొ గొ చొ …; ఓత్వం (ో): కో గో చో …","చిత్రాలు: కొడవలి, బొంగరం, కోడి, టోపి.","పదాలు: పొద, రొద, కొండ, తొండ, దొండ; కోట, తోట, కోడి, జోడి; తొడుగు, గొడుగు, పొడుగు, మోకాలు; కోడెనాగు, కోడికూత, కోటగోడ, కోతితోక, దోమతెర; కోలాటం, తోరణం, వినోదం, పూలతోట, జోలపాట; కొండవాగు, కొండచిలువ, పొడుపుకథ, కోడిపుంజు, గోవిందుడు.","వాక్యాలు: తోటలోన తొండ ఉంది. కొండమీద కోతి ఉంది. చెరువులోన కొంగ ఉంది. మడుగులోన మొసలి ఉంది.","గబగబ పలకండి: కోటపైన కోతి – గోడమీద గోలీ.","పద్యం: అన్నిదానములను నన్నదానమే గొప్ప / కన్నవారికంటె ఘనులు లేరు / ఎన్న గురుని కన్న నెక్కువ లేరయా / విశ్వదాభిరామ వినురవేమ! – భావం: అన్ని దానాల్లో అన్నదానమే గొప్పది; తల్లిదండ్రులను మించిన గొప్పవారు లేరు; గురువును మించిన వారు లేరు."],"w":[["కొంటె","అల్లరి"],["పిందెలు","లేత కాయలు"],["ప్రీతి","ఇష్టం"],["లొట్టలు","నోరూరడం"],["దూకుడు","దూకడం"],["కుదురు","నిలకడ"],["గోపురం","గుడి శిఖరం"],["గంతు","ఎగురు"],["తొండ","ఊసరవెల్లి వంటి జీవి"],["కోలాటం","కర్రలతో ఆడే జానపద నృత్యం"]],"gr":{"t":"ఒత్వం (ొ), ఓత్వం (ో)","p":["ఒత్వం: కొ గొ చొ జొ టొ డొ ణొ తొ దొ నొ పొ బొ మొ యొ రొ లొ వొ శొ షొ సొ హొ ళొ","ఓత్వం: కో గో చో జో టో డో ణో తో దో నో పో బో మో యో రో లో వో శో షో సో హో ళో","“ర” కి ఓత్వం చేరిస్తే “రో”. పలీసు→పోలీసు, సమవారం→సోమవారం.","ఒత్వం పదాలు: గొడుగు, కొడవలి, బొంగరం; ఓత్వం పదాలు: కోతి, కోడి, టోపి, తోట."]},"qa":[["కోతి బావకు దేనిపై ఇష్టం ఎక్కువ?","కొబ్బరిపై."],["కోతి బావకు ఏది తక్కువ?","కుదురు."],["గుడి గోపురమెక్కితే కోతికి ఏవి ఎక్కువ?","గంతులు."],["కోతులు ఇంటి పెరట్లోకి వస్తే ఏం చేస్తాయి?","పండ్లు, పిందెలు తెంపుతాయి, బట్టలు లాగుతాయి, అల్లరి చేస్తాయి."],["జంతువులను ఎందుకు బాధపెట్టకూడదు?","వాటికీ ప్రాణం, నొప్పి ఉంటుంది; అవి ప్రకృతిలో భాగం."]],"act":"గేయాన్ని అభినయిస్తూ పాడండి. చుక్కలు కలిపి గొడుగు బొమ్మ గీసి రంగులు వేయండి. జంతువుల పేర్లు, వాటి పట్ల మనం ఎలా ప్రవర్తించాలో తెలుసుకోండి.","kn":"కోతులకు కొబ్బరి, అరటిపండ్లు అంటే ఇష్టం. జంతువులకు ఆహారం విసిరి వేయకూడదు, రాళ్ళు వేయకూడదు – దయగా చూడాలి.","qz":[["“కొంటె కోతి” గేయ రచయిత","కస్తూరి నరసింహమూర్తి","జై సీతారాం","గురజాడ అప్పారావు","నాగభైరవ ఆది నారాయణ"],["“కోతిబావ నీకు కాస్త ___ ఎక్కువ”","కోపం","కుదురు","నిద్ర","భయం"],["“___ అంటే చాలు నీకు ఇష్టమెక్కువ”","కొబ్బరి","రొట్టె","అరటి","జామ"],["కోతి బావకు తక్కువైనది","కుదురు","కోపం","దూకుడు","గంతులు"],["“గుడి గోపురమెక్కితే ___ ఎక్కువ”","గంతులు","లొట్టలు","కోపం","దూకుడు"],["గొడుగు చిత్రానికి పదం","గొడుగు","కోతి","గోడ","కోడి"],["“ర” కి ఓత్వం చేరిస్తే","రో","రి","రొ","రా"],["“తోట” లో ఏ గుణింతం?","ఓత్వం","ఒత్వం","ఎత్వం","గుడి"],["మనం రోజూ తినే ఆహారానికి సంబంధించిన పదం","వరిపొలం","కొండచిలువ","జోలపాట","కోలాటం"],["__ కాలు (మో)","మో","తో","చో","కో"],["“కోటపైన కోతి – గోడమీద ___”","గోలీ","కోడి","కొంగ","తొండ"],["కొండమీద ఏముంది?","కోతి","తొండ","కొంగ","మొసలి"]],"tg":[["చిత్రం చూడండి (పుట 21)",["గుడి గోడ, గోపురంపై కోతులు దూకుతున్నాయి; కొబ్బరి చెట్టుపై కోతి; పండ్ల బండి దగ్గర కోతులు; ఒక కుటుంబం చూస్తోంది."]],["వినండి – మాట్లాడండి (పుట 22)",["ఆ) గోడ మీద, కొబ్బరి చెట్టు మీద, గుడి గోపురం మీద, పండ్ల బండి దగ్గర.","ఇ) కొబ్బరి, రొట్టెముక్క, పిందెలు, అరటిపండ్లు.","ఈ) పండ్లు, పిందెలు తెంపుతాయి; బట్టలు లాగుతాయి; ఇంట్లోకి దూరి వస్తువులు ఎత్తుకెళ్తాయి.","ఉ) చిత్రం: కోతులు నడుస్తున్నాయి (నడవడం), పండ్లు తింటున్నాయి (తినడం), కొమ్మలకు వేలాడి ఊగుతున్నాయి (ఊగడం)."]],["చదవండి (పుటలు 22–23)",["ఆ) గొడుగు – “గొ”, కోతి – “కో” కు సున్నా.","ఈ) కొడవలి, బొంగరం, కోడి, టోపి – పేర్లు చదవాలి.","ఊ) తోటలోన తొండ, కొండమీద కోతి, చెరువులోన కొంగ, మడుగులోన మొసలి."]],["రాయండి (పుట 24)",["ఒత్వం: కొ గొ చొ జొ టొ డొ ణొ తొ దొ నొ పొ / బొ మొ యొ రొ లొ వొ శొ షొ సొ హొ ళొ","ఓత్వం: కో గో చో జో టో డో ణో తో దో నో పో / బో మో యో రో లో వో శో షో సో హో ళో","ఆ) గళ్ళ పదాలు: కోతి, గొడుగు, కోడి, తోట, సొగసు, దోసె"]],["నేనేమి నేర్చుకున్నాను? (పుట 25)",["1) ఆ) గొడుగు  2) కోడి  3) ఆ) రో","4) పలీసు → పోలీసు; సమవారం → సోమవారం","5) మనం రోజూ తినే ఆహారానికి సంబంధించినది: అ) వరిపొలం (బియ్యం వరి నుండి వస్తుంది)","6) 1) మోకాలు  2) తోడేలు  3) చొరవ","7) జంతువులకూ నొప్పి, ప్రాణం ఉంటాయి; అవి ప్రకృతి సమతుల్యతకు అవసరం."]]],"wb":{"pg":"22–26","f":"books/2/Class2_Workbook_Sem1.pdf","p":28,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"ఒత్వం (ొ) – కొ, ఓత్వం (ో) – కో తేడా: గొడుగు (గొ), కోతి (కో).","qz":[["గొడుగు చిత్రానికి పదం","గొడుగు","కోతి","గోడ","గుడి"],["కోడి చిత్రానికి పదం","కోడి","కొడి","కోడీ","కాడి"],["“ర” కి ఓత్వం","రో","రొ","రె","రా"],["__ పి (టోపి)","టో","టొ","టా","టె"],["__ సలి (మొసలి)","మొ","మో","మా","ము"],["కొన + డం =","కొనడం","కోనడం","కొనదం","కనడం"],["చెరువులో ___ ఉంది","మొసలి","కోతి","తొండ","కోడి"],["రోజాకి ___ కావాలి","గొలుసు","గెల","బజ్జీ","దీపం"],["“జోలపాట సరిత పాడింది” సరిచేస్తే","సరిత జోలపాట పాడింది","పాడింది జోలపాట సరితకు","జోల సరిత పాట","సరితకు జోలపాట పాడు"],["ఉదయాన్నే లేస్తాను, కొక్కొరొకో అంటాను","కోడిపుంజు","కాకి","కోతి","చిలుక"],["బొంగరం – మొదటి అక్షరం","బొం","బో","బం","బ"],["తోటలో ___ కాయలు కాశాయి","దొండ","గొడుగు","కోడి","గోడ"]]}},{"id":"te6","no":6,"t":"ఏ ఊరెళదాం?","m":[9],"ty":"గేయం","th":"ప్రయాణ సాధనాలు (ఐత్వం ై, ఔత్వం ౌ)","by":"నాగభైరవ ఆది నారాయణ – తెలుగు లోగిలి – 2 (పుటలు 26–30)","sum":"ప్రయాణ సాధనాలతో ఊళ్ళు తిరిగే గేయం: “బండెక్కి మనము ఏ ఊరెళదాం? బండెక్కి మనము బద్వేలు వెళదాం / సైకిలెక్కి మనము ఏ ఊరెళదాం? సైకిలెక్కి మనము శ్రీశైలం వెళదాం / నౌకెక్కి మనము ఏ ఊరెళదాం? నౌకెక్కి మనము విశాఖ వెళదాం / రైలెక్కి మనము ఏ ఊరెళదాం? రైలెక్కి మనము రేణిగుంట వెళదాం / విమానమెక్కి మనము ఏ ఊరెళదాం? విమానమెక్కి మనము వెయ్యూళ్ళెళదాం”. ఐత్వం (ై), ఔత్వం (ౌ) – రైలు, నౌక, మైకు, టైరు, సైకిలు, గౌను.","pts":["గేయ రచయిత: నాగభైరవ ఆది నారాయణ.","బండి – బద్వేలు; సైకిలు – శ్రీశైలం; నౌక – విశాఖ; రైలు – రేణిగుంట; విమానం – వెయ్యూళ్ళు.","చిత్రకథ: మైలవరం పాఠశాల పిల్లలు బస్సులో విహార యాత్రకు వెళ్తున్నారు. ఒక పెద్దావిడ బస్సు ఎక్కలేక ఇబ్బంది పడుతుంటే ప్రణవి, అంజలి ఆమె చేయి పట్టుకుని బస్సు ఎక్కించారు. ఉపాధ్యాయులు వారిని మెచ్చుకున్నారు.","ఐత్వం (ై): కై గై చై …; ఔత్వం (ౌ): కౌ గౌ చౌ …","పదాలు: పైరు, జైలు, టైరు, మైలు, వైరు, రైలు; తైలం, మైనం, దైవం, వైనం, పైకం, శైవం; కైకలూరు, మైదుకూరు, నైనవరం, మైలవరం; గౌరి, శౌరి, చౌక, నౌక, ఔను, గౌను, తౌడు, దౌడు; పౌడరు, నౌకరు, గౌరవం, పౌరుషం; నౌకాయానం, చౌకబేరం, కౌతవరం, కౌరవులు.","పేరా: అనగనగా ఒక రైతు. ఐదు ఎకరాల పొలం. బాగా పనిచేసేవాడు. పంటలు బాగా పండించేవాడు. గౌరవంగా బతికేవాడు.","గబగబ పలకండి: మూడు ఎర్రలారీలు, ఆరు నల్లలారీలు.","పద్యం: అన్నిదానములను నన్నదానమే గొప్ప / కన్నవారికంటె ఘనులు లేరు / ఎన్న గురుని కన్న నెక్కువ లేరయా / విశ్వదాభిరామ వినురవేమ! – భావం: అన్ని దానాల్లో అన్నదానమే గొప్పది; తల్లిదండ్రులను మించిన గొప్పవారు లేరు; గురువును మించిన వారు లేరు."],"w":[["నౌక","ఓడ"],["విమానం","ఆకాశంలో ఎగిరే వాహనం"],["వెయ్యూళ్ళు","వెయ్యి ఊళ్ళు, ఎన్నో ఊళ్ళు"],["విహారయాత్ర","విహారానికి చేసే ప్రయాణం"],["పైరు","పంట"],["తైలం","నూనె"],["దైవం","దేవుడు"],["పైకం","డబ్బు"],["తౌడు","వడ్ల పొట్టు"],["గౌరవం","మర్యాద"]],"gr":{"t":"ఐత్వం (ై), ఔత్వం (ౌ)","p":["ఐత్వం: కై గై చై జై టై డై ణై తై దై నై పై బై మై యై రై లై వై శై షై సై హై ళై","ఔత్వం: కౌ గౌ చౌ జౌ టౌ డౌ ణౌ తౌ దౌ నౌ పౌ బౌ మౌ యౌ రౌ లౌ వౌ శౌ షౌ సౌ హౌ ళౌ","ఐత్వం పదాలు: రైలు, మైకు, టైరు, సైకిలు, కైక; ఔత్వం పదాలు: నౌక, గౌను, చౌక, మౌన.","ఐత్వంతో మొదలయ్యే ఊళ్ళు: కైకలూరు, మైదుకూరు, మైలవరం, నైనవరం."]},"qa":[["నౌకెక్కి ఏ ఊరు వెళదాం అన్నారు?","విశాఖ."],["రైలెక్కి ఏ ఊరు వెళదాం అన్నారు?","రేణిగుంట."],["సైకిలెక్కి ఏ ఊరు?","శ్రీశైలం."],["ప్రణవి, అంజలి ఎవరికి సాయం చేశారు?","బస్సు ఎక్కలేని పెద్దావిడకు."],["పాఠశాలకు సమయపాలన ఎందుకు పాటించాలి?","పాఠాలు, ప్రార్థన మిస్ కాకుండా, క్రమశిక్షణ కోసం."]],"act":"గేయాన్ని అభినయిస్తూ పాడండి. చుక్కలు కలిపి నౌక బొమ్మ గీసి రంగులు వేయండి. నేల, నీటి, వాయు మార్గాల్లో ప్రయాణ సాధనాల పేర్లు సేకరించండి.","kn":"నేల మార్గం: బస్సు, రైలు, కారు, సైకిలు, బండి • నీటి మార్గం: పడవ, నౌక, ఓడ • వాయు మార్గం: విమానం, హెలికాప్టర్.","qz":[["“ఏ ఊరెళదాం?” గేయ రచయిత","నాగభైరవ ఆది నారాయణ","కస్తూరి నరసింహమూర్తి","మూలం శాంతివనం","జై సీతారాం"],["బండెక్కి ఏ ఊరు వెళదాం?","బద్వేలు","విశాఖ","రేణిగుంట","శ్రీశైలం"],["సైకిలెక్కి ఏ ఊరు?","శ్రీశైలం","బద్వేలు","విశాఖ","రేణిగుంట"],["నౌకెక్కి ఏ ఊరు?","విశాఖ","శ్రీశైలం","బద్వేలు","రేణిగుంట"],["రైలెక్కి ఏ ఊరు?","రేణిగుంట","విశాఖ","శ్రీశైలం","బద్వేలు"],["విమానమెక్కి","వెయ్యూళ్ళు","విశాఖ","బద్వేలు","శ్రీశైలం"],["పిల్లలందరూ ఎక్కడికి వెళ్తున్నారు?","విహారయాత్రకు","ఊరికి","పాఠశాలకు","గుడికి"],["పిల్లలు ఎవరిని చూశారు?","పెద్దావిడను","స్నేహితులను","ఉపాధ్యాయులను","పోలీసును"],["ఐత్వం, ఔత్వం ఉండే పదాలు","కైకేయి, గౌను","కొంటె, కోతి","కాకర, నేల","చేప, తాబేలు"],["మేరి ముఖానికి ___ రాసుకుంది","పౌడరు","పైరు","అద్దం","గౌను"],["సముద్రపు ప్రయాణానికి సంబంధించిన పదం","నౌకాయానం","కౌరవులు","గౌరీరాగం","చౌకబేరం"],["“మౌన” తో జతపరిచే పదం","పఠనం","బేరం","నౌక","గౌను"]],"tg":[["చిత్రం చూడండి (పుట 26)",["రైలు, విమానం, నౌక, సైకిలు, ఎడ్ల బండి – వివిధ ప్రయాణ సాధనాలతో కుటుంబాలు ప్రయాణిస్తున్నాయి."]],["వినండి – మాట్లాడండి (పుట 27)",["ఆ) రైలు, విమానం, నౌక, సైకిలు, బండి.","ఇ) బస్సులో అమ్మమ్మ ఊరికి, రైలులో తిరుపతికి (విద్యార్థి అనుభవం).","ఈ) రైలు ఇష్టం – కిటికీ నుండి పొలాలు, చెట్లు చూడవచ్చు (ఉదా).","ఉ) 1. ఆ) విహారయాత్రకు  2. ఇ) పెద్దావిడను  3. అ) మంచిపని చేసినందుకు"]],["చదవండి (పుటలు 27–28)",["అ) రైలు – “రై”, నౌక – “నౌ” కు సున్నా.","ఇ) జతపరచడం: టైరు – టైరు బొమ్మ, మైకు – మైక్ బొమ్మ, సైకిలు – సైకిలు, గౌను – గౌను బొమ్మ.","ఉ) 1. ఆ రైతు  2. పంటలు  3. గౌరవం (గౌరవంగా)"]],["రాయండి (పుట 29)",["ఐత్వం: కై గై చై జై టై డై ణై తై దై నై పై / బై మై యై రై లై వై శై షై సై హై ళై","ఔత్వం: కౌ గౌ చౌ జౌ టౌ డౌ ణౌ తౌ దౌ నౌ పౌ / బౌ మౌ యౌ రౌ లౌ వౌ శౌ షౌ సౌ హౌ ళౌ","ఆ) కైక, గౌను, రైలు, నౌక, మైకు, టైరు, చౌక, పైరు"]],["నేనేమి నేర్చుకున్నాను? (పుట 30)",["1) ఆ) కైకేయి, గౌను  2) రైలు  3) అ) పౌడరు","4) ఎ) మౌన – 2) పఠనం (మౌన పఠనం); బి) చౌక – 1) బేరం (చౌకబేరం)","5) ఇ) నౌకాయానం","6) ఐత్వంతో మొదలయ్యే ఊళ్ళు: కైకలూరు, మైదుకూరు (మైలవరం)","7) ప్రార్థన, మొదటి పాఠం మిస్ కాకూడదు; క్రమశిక్షణ అలవడుతుంది; ఉపాధ్యాయులకు గౌరవం."]]],"wb":{"pg":"27–31","f":"books/2/Class2_Workbook_Sem1.pdf","p":33,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"ఐత్వం (ై) – కై, ఔత్వం (ౌ) – కౌ తేడా: రైలు (రై), నౌక (నౌ).","qz":[["ఐత్వం (ై) ఉన్న అక్షరం","రై","రౌ","రొ","రె"],["ఔత్వం (ౌ) ఉన్న అక్షరం","నౌ","నై","నో","నె"],["పంటలు పండించేవారు","రైతు","వడ్రంగి","జాలరి","కుమ్మరి"],["₹50 నోటు","యాభై రూపాయలు","ఇరవై రూపాయలు","నలభై రూపాయలు","వంద రూపాయలు"],["చౌక ___","బేరం","చైను","పిండి","బండి"],["రైలు ___","బండి","బేరం","చైను","పిండి"],["__ రు (టైరు)","టై","టౌ","టొ","టా"],["__ ను (గౌను)","గౌ","గై","గో","గా"],["శైలజకి ___ కావాలి","సైకిలు","కోడి","గూడు","చీమ"],["రెండు చక్రాల గుర్రం నేను – మేత మేయను","సైకిలు","రైలు","బండి","బస్సు"],["“మౌనిక పూసుకుంది పౌడరు” సరిచేస్తే","మౌనిక పౌడరు పూసుకుంది","పౌడరు మౌనికను పూసింది","మౌనిక పౌడరుకు పూసుకుంది","పూసుకుంది పౌడరుతో మౌనికను"],["గజిబిజి “లుసపై” సరిచేస్తే","పైసలు","సలుపై","లుపైస","పైలుస"]]}},{"id":"te7","no":7,"t":"అప్పడాలు – బజ్జీలు","m":[10],"ty":"గేయం","th":"ఆహారం, ఆరోగ్యం (ప్ప, జ్జ ఒత్తులు)","by":"మూలం: శాంతి వనం – తెలుగు లోగిలి – 2 (పుటలు 31–35)","sum":"అతిగా తింటే కడుపునొప్పి వస్తుందని చెప్పే హాస్య గేయం: “చింతకాయ దప్పళం / పప్పూ వేసి కలపటం / అప్పడాలు వేపడం / కరకరమని నమలటం / బజ్జీలను తేవడం / బొజ్జ నిండ మెక్కటం / కడుపు నొప్పి రావడం / మంచ మెక్కి దొర్లటం / దుకాణాని కెళ్ళడం / శొంటికొమ్ము తేవటం / నమిలి నీళ్ళు మింగడం / కడుపునొప్పి పోవటం / బుద్ధితెచ్చు కోవడం”. “ప” ఒత్తు (ప్ప), “జ” ఒత్తు (జ్జ) – అప్పడాలు, బజ్జీలు, కప్ప, గజ్జెలు, బొప్పాయి.","pts":["గేయం: చింతకాయ దప్పళం, అప్పడాలు, బజ్జీలు బొజ్జ నిండా తిని కడుపు నొప్పి; శొంటికొమ్ము నమిలి నీళ్ళు తాగితే నొప్పి పోయింది; బుద్ధి తెచ్చుకున్నాడు.","మూలం: శాంతి వనం.","నీతి: అతిగా తినకూడదు; ఆరోగ్యకర ఆహారం, మితంగా తినాలి.","ఒత్తు: ఒక హల్లు కింద అదే హల్లు చిన్నగా – ప + ్ప = ప్ప, జ + ్జ = జ్జ.","చిత్రాలు: కప్ప, కజ్జికాయలు, గజ్జెలు, బొప్పాయి.","పదాలు: సజ్జ, బొజ్జ, గుజ్జు, నుజ్జు, బుజ్జి, గజ్జి, బెజ్జం; అప్పు, ముప్పు, కప్పు, ఉప్పు, తప్పు, ఒప్పు; సజ్జలు, గజ్జెలు, మజ్జిగ, బుజ్జాయి; ఉప్పెన, చప్పన, రెప్పలు, మొప్పలు, చెప్పులు; అప్పడం, దప్పళం, పంటినొప్పి, కడుపునొప్పి, కందిపప్పు; పూల సజ్జ, తాత బొజ్జ, బుజ్జి మేక, అరటి బజ్జి, మిరప బజ్జి.","బజ్జీల గేయం: బజ్జీలండి బజ్జీలు – వేడి వేడి బజ్జీలు / కారం కారం బజ్జీలు – మిరపకాయ బజ్జీలు / నోరూరించే బజ్జీలు – బంగాళదుంప బజ్జీలు / ఘుమఘుమ లాడే బజ్జీలు – అరటికాయ బజ్జీలు / అతిగా తింటే ముప్పండి – అందరికీ ఇది చెప్పండి.","గబగబ పలకండి: బుజ్జి బజ్జీలు తిని బజ్జుంది.","పద్యం: కష్టపెట్టబోకు కన్నతల్లి మనసు / నష్టపెట్టబోకు నాన్నపనులు / తల్లిదండ్రులన్న దైవసన్నిభులురా / లలితసుగుణజాల! తెలుగుబాల! – భావం: కన్నతల్లి మనసును బాధపెట్టకూడదు; నాన్న పనులకు నష్టం కలిగించకూడదు; తల్లిదండ్రులు దైవంతో సమానం."],"w":[["దప్పళం","పులుసు"],["అప్పడాలు","వడియాల వంటి వేయించే పదార్థం"],["బొజ్జ","కడుపు"],["మెక్కటం","అతిగా తినడం"],["శొంటికొమ్ము","ఎండు అల్లం"],["బుద్ధి","తెలివి"],["మజ్జిగ","పెరుగు నీరు"],["సజ్జ","బుట్ట / ఒక ధాన్యం"],["ఉప్పెన","సముద్రపు అలల ముప్పు"],["ముప్పు","ప్రమాదం"]],"gr":{"t":"ఒత్తులు – ప్ప, జ్జ","p":["ప్ప గుణింతం: ప్ప ప్పా ప్పి ప్పీ ప్పు ప్పూ ప్పృ ప్పె ప్పే ప్పై ప్పొ ప్పో ప్పౌ ప్పం","జ్జ గుణింతం: జ్జ జ్జా జ్జి జ్జీ జ్జు జ్జూ జ్జృ జ్జె జ్జే జ్జై జ్జొ జ్జో జ్జౌ జ్జం","ఒత్తు గల, ఒత్తు లేని పదాల తేడా: కప (కఫం) – కప్ప; పట – పట్టు.","ఉదా: బొప్పాయి తింటే కంటికి మంచిది. బుజ్జాయికి కజ్జికాయలు కావాలి."]},"qa":[["అప్పడాలు ఎలా నమిలాడు?","కరకరమని."],["బజ్జీలు బొజ్జ నిండా తింటే ఏమైంది?","కడుపు నొప్పి వచ్చింది."],["కడుపు నొప్పి ఎలా పోయింది?","శొంటికొమ్ము నమిలి నీళ్ళు మింగితే."],["బజ్జీలు అతిగా తింటే?","అందరికీ ముప్పు."],["ఆకలి వేసిన వారికి అన్నం పెట్టడం ఎందుకు మంచిది?","అన్నదానం గొప్పది; ఆకలి తీరితే వారు సంతోషిస్తారు."]],"act":"గేయాన్ని అభినయిస్తూ పాడండి. చుక్కలు కలిపి కప్ప బొమ్మ గీసి రంగులు వేయండి. మనం రోజూ తినే ఆహార పదార్థాలు ఎంతవరకు, ఎప్పుడెప్పుడు తీసుకోవాలో తెలుసుకోండి.","kn":"రోజుకు మూడుసార్లు సమయానికి తినాలి; ఉదయం అల్పాహారం మానకూడదు; నూనె పదార్థాలు, జంక్ ఫుడ్ తక్కువగా; పండ్లు, కూరగాయలు ఎక్కువగా తినాలి.","qz":[["“అప్పడాలు – బజ్జీలు” గేయం మూలం","శాంతి వనం","గురజాడ అప్పారావు","జై సీతారాం","వేమన"],["అప్పడాలు ఎలా నమిలాడు?","కరకరమని","గబగబ","మెల్లగా","చప్పుడు లేకుండా"],["బొజ్జ నిండ మెక్కినవి","బజ్జీలు","అప్పడాలు","పండ్లు","అన్నం"],["కడుపు నొప్పి వస్తే ఏమి తెచ్చాడు?","శొంటికొమ్ము","మాత్రలు","మజ్జిగ","పండ్లు"],["ఇచ్చిన చిత్రాల పేర్లు (బజ్జీలు, గజ్జెలు)","బజ్జీలు, గజ్జెలు","బజీలు, గజెలు","బజ్జీలు, గజ్జెళ్ళు","బజీలు, గజ్జెలు"],["“జ్జ” ఒత్తు లేని పదం","డబ్బా","పూలసజ్జ","మజ్జిగ","గజ్జెలు"],["కళ్ళకు రక్షణగా ఉండేవి","రెప్పలు","చెప్పులు","మొప్పలు","కప్పులు"],["“నోరూరించే బజ్జీలు”","బంగాళదుంప బజ్జీలు","అరటికాయ బజ్జీలు","మిరపకాయ బజ్జీలు","అందరికీ ముప్పు"],["“కారం కారం బజ్జీలు”","మిరపకాయ బజ్జీలు","అరటికాయ బజ్జీలు","బంగాళదుంప బజ్జీలు","అందరికీ ముప్పు"],["“బజ్జీలు అతిగా తింటే”","అందరికీ ముప్పు","బంగాళదుంప బజ్జీలు","మిరపకాయ బజ్జీలు","అరటికాయ బజ్జీలు"],["సరిచేసిన వాక్యం","బొప్పాయి తింటే కంటికి మంచిది","బొపాయి తింటే కంటికి మంచిది","బోపాయి తింటే కంటికి మంచిది","బొప్పయి తింటే కంటికి మంచిది"],["ప్ప గుణింతం: ప్ప, ప్పా, ___, ప్పీ","ప్పి","ప్పు","ప్పె","ప్పో"]],"tg":[["చిత్రం చూడండి (పుట 31)",["ఒక బాబు అరటి ఆకులో అప్పడాలు, బజ్జీలు తింటున్నాడు; తర్వాత కడుపు నొప్పితో మంచంపై దొర్లుతున్నాడు; జనరల్ స్టోర్‌కు వెళ్తున్నాడు."]],["వినండి – మాట్లాడండి (పుట 32)",["ఆ) బాబు అతిగా తిని కడుపు నొప్పితో బాధపడ్డాడు; శొంటికొమ్ము నమిలి నొప్పి తగ్గించుకున్నాడు.","ఇ) శొంటికొమ్ము నమిలి నీళ్ళు తాగాడు; నేనైతే అమ్మకు చెప్పి వైద్యుని దగ్గరకు వెళ్తాను, ఇకపై అతిగా తినను.","ఈ) పప్పు అన్నం, పెరుగు, ఇడ్లీ, పండ్లు (విద్యార్థి ఇష్టం).","ఉ) చిత్రం: అమ్మ పిల్లలకు అరటి ఆకుల్లో భోజనం వడ్డిస్తోంది; అందరూ కింద కూర్చుని తింటున్నారు."]],["చదవండి (పుటలు 32–33)",["ఆ) అప్పడాలు – “ప్ప”, బజ్జీలు – “జ్జీ” కు సున్నా.","ఉ) జతపరచడం: 1. నోరూరించే బజ్జీలు – బంగాళదుంప బజ్జీలు  2. కారం కారం బజ్జీలు – మిరపకాయ బజ్జీలు  3. అతిగా తింటే – అందరికీ ముప్పు  4. ఘుమఘుమ లాడే – అరటికాయ బజ్జీలు"]],["రాయండి (పుట 34)",["ప్ప: ప్ప ప్పా ప్పి ప్పీ ప్పు ప్పూ ప్పృ ప్పె ప్పే ప్పై ప్పొ ప్పో ప్పౌ ప్పం","జ్జ: జ్జ జ్జా జ్జి జ్జీ జ్జు జ్జూ జ్జృ జ్జె జ్జే జ్జై జ్జొ జ్జో జ్జౌ జ్జం","అప్పడం: కప్పు, ఉప్పు, చెప్పులు • పూలసజ్జ: మజ్జిగ, బుజ్జి, గజ్జెలు","ఆ) గళ్ళ పదాలు: అప్పులు, సజ్జ, బుజ్జి, మగ (ఉదా: సఅప్పులు → అప్పులు; జ్జబుజ్జిప్ప → బుజ్జి)"]],["నేనేమి నేర్చుకున్నాను? (పుట 35)",["1) అ) బజ్జీలు, గజ్జెలు  2) కప్ప  3) అ) డబ్బా","4) ప్ప ప్పా ప్పి ప్పీ ప్పు ప్పూ ప్పృ ప్పె ప్పే ప్పై ప్పొ ప్పో ప్పౌ ప్పం","5) ఇ) రెప్పలు","6) 1) బొప్పాయి తింటే కంటికి మంచిది.  2) బుజ్జాయికి కజ్జికాయలు కావాలి.","7) ఆకలి బాధ తీరుతుంది; అన్నదానం అన్ని దానాల్లో గొప్పది; వారు సంతోషిస్తారు."]]],"wb":{"pg":"32–36","f":"books/2/Class2_Workbook_Sem1.pdf","p":38,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"ఒత్తు అక్షరం: ప + ్ప = ప్ప, జ + ్జ = జ్జ. “బొపాయి” తప్పు – “బొప్పాయి” సరైనది.","qz":[["ఒక్క కిలో కంది పప్పు ఎంత?","ముప్పై రూపాయలు","మూడు రూపాయలు","మూడు వందల రూపాయలు","ముప్పై పైసలు"],["ఉప్పు లేని కూర ఎలా ఉంటుంది?","చప్పగా","తీయగా","చేదుగా","కారంగా"],["కాళ్ళకు ముళ్ళు గుచ్చుకోకుండా వేసుకునేవి","చెప్పులు","పట్టీలు","పారాణి","గజ్జెలు"],["క __ (కప్ప)","ప్ప","జ్జ","బ్బ","ళ్ళ"],["గ __ లు (గజ్జెలు)","జ్జె","ప్పె","జ్జు","బ్బె"],["తాత ___ తాగాడు","మజ్జిగ","గజ్జెలు","చెప్పులు","కప్ప"],["ఉప్పు లేని పప్పు ___","చప్పన","తీపి","కారం","చేదు"],["బుజ్జిపాపకు ___ కావాలి","బజ్జీలు","చీమ","కోడి","నౌక"],["నీటిలో పుడతాను, నీటిలోనే కరుగుతాను","ఉప్పు","చక్కెర","మంచు","సబ్బు"],["“జ్జ” ఒత్తు పదం","మజ్జిగ","కప్ప","ఉప్పు","చెప్పు"],["“ప్ప” ఒత్తు పదం","బొప్పాయి","బజ్జీ","గజ్జెలు","సజ్జ"],["కళ్ళ పైన ఉండేవి","కనురెప్పలు","చెప్పులు","గజ్జెలు","దుప్పటి"]]}},{"id":"te8","no":8,"t":"సబ్బుబిళ్ళ","m":[10],"ty":"గేయం","th":"పరిశుభ్రత (బ్బ, ళ్ళ ఒత్తులు)","by":"అలపర్తి వెంకట సుబ్బారావు – తెలుగు లోగిలి – 2 (పుటలు 36–40)","sum":"కాకి సబ్బుబిళ్ళను ఎత్తుకెళ్ళిన సరదా గేయం: “కాకి ఎత్తుకెళ్ళె మా సబ్బుబిళ్ళ! / కాకి ఏమిజేయు నా సబ్బుబిళ్ళ! / కాకి కున్నదేమొ ఓ చంటిపిల్ల / ఒళ్ళు రుద్దనేమో ఆ సబ్బుబిళ్ళ / సబ్బు రుద్దగానే ఆ కాకిపిల్ల / మిలమిలా మెరిసింది ఎందువల్ల? / రుద్దుకొనుట ఎందుకో సబ్బుబిళ్ళ / మురికి పోవడానికే కాకిపిల్ల / కాకికీ ముద్దుకదా కాకిపిల్ల / అందుకే రుద్దె గదా సబ్బుబిళ్ళ!!”. “బ” ఒత్తు (బ్బ), “ళ” ఒత్తు (ళ్ళ) – సబ్బుబిళ్ళ, పళ్ళెం, కళ్ళు, మబ్బు, గొళ్ళెం.","pts":["గేయ రచయిత: అలపర్తి వెంకట సుబ్బారావు.","కాకి సబ్బుబిళ్ళ ఎత్తుకెళ్ళి తన కాకిపిల్ల ఒళ్ళు రుద్దింది – మురికి పోయి కాకిపిల్ల మిలమిలా మెరిసింది. కాకికి తన పిల్ల ముద్దు కదా!","చిత్రకథ: బళ్ళో రాజు రబ్బరు బంతితో క్రికెట్ ఆడి ఇంటికి చేరాడు. ఒళ్ళంతా చెమట పట్టి ఉండటం చూసి అమ్మ సబ్బుతో స్నానం చేయమంది. కుళాయి వద్ద కుమార్తె కళావతి చేతులు సబ్బుతో శుభ్రం చేసుకోవడం గమనించి, నీళ్ళు పొదుపుగా వాడమని చెప్పింది. తర్వాత ఇంట్లో మాసిన బట్టలు సబ్బుతో ఉతికింది.","ఒత్తులు: బ్బ – సబ్బు, మబ్బు, డబ్బు, అబ్బాయి; ళ్ళ – బిళ్ళ, కళ్ళు, నీళ్ళు, పెళ్ళి, పళ్ళెం.","చిత్రాలు: సబ్బుబిళ్ళ, పళ్ళెం; మబ్బు, కొబ్బరికాయ, కళ్ళు, గొళ్ళెం.","పదాలు: దెబ్బ, దిబ్బ, జబ్బ, జుబ్బ, మబ్బు; ముళ్ళు, కళ్ళు, కాళ్ళు, వాళ్ళు, వీళ్ళు, రాళ్ళు; డబ్బు, సబ్బు, రుబ్బు, దుబ్బు, అబ్బాయి, డబ్బాలు; కళ్ళెం, పళ్ళెం, జోళ్ళు, నీళ్ళు, పెళ్ళి, కిళ్ళీ; సిబ్బి రేకు, గొబ్బి పాట, రుబ్బు రోలు, డబ్బు సంచి, వెండి పళ్ళెం, తలుపుగొళ్ళెం; గుళ్ళోపెళ్ళి, బళ్ళో చదువు, కళ్ళజోడు, కాలి జోళ్ళు, కొబ్బరి నీళ్ళు, గులాబి ముళ్ళు.","పేరా: సుబ్బులు, అబ్బులు సంతకు వెళ్ళారు. సుబ్బులు సబ్బుబిళ్ళ కొన్నది. అబ్బులు కళ్ళజోడు కొన్నాడు. మబ్బులు వేశాయి; వాన కురిసి సంతలో నీళ్ళు చేరాయి.","గబగబ పలకండి: సంతలో సుబ్బులు, అబ్బులు సబ్బుబిళ్ళలు కొన్నారు.","పద్యం: కష్టపెట్టబోకు కన్నతల్లి మనసు / నష్టపెట్టబోకు నాన్నపనులు / తల్లిదండ్రులన్న దైవసన్నిభులురా / లలితసుగుణజాల! తెలుగుబాల! – భావం: కన్నతల్లి మనసును బాధపెట్టకూడదు; నాన్న పనులకు నష్టం కలిగించకూడదు; తల్లిదండ్రులు దైవంతో సమానం."],"w":[["బిళ్ళ","ముక్క"],["ఒళ్ళు","శరీరం"],["చంటిపిల్ల","చిన్న బిడ్డ"],["మిలమిల","మెరుస్తూ"],["మురికి","మలినం"],["ముద్దు","ప్రియమైనది"],["గొళ్ళెం","తలుపు గడియ"],["కిళ్ళీ","తాంబూలం"],["రుబ్బు రోలు","పిండి రుబ్బే రాతి రోలు"],["పొదుపు","వృథా చేయకుండా వాడటం"]],"gr":{"t":"ఒత్తులు – బ్బ, ళ్ళ","p":["బ్బ గుణింతం: బ్బ బ్బా బ్బి బ్బీ బ్బు బ్బూ బ్బృ బ్బె బ్బే బ్బై బ్బొ బ్బో బ్బౌ బ్బం","ళ్ళ గుణింతం: ళ్ళ ళ్ళా ళ్ళి ళ్ళీ ళ్ళు ళ్ళూ ళ్ళృ ళ్ళె ళ్ళే ళ్ళై ళ్ళొ ళ్ళో ళ్ళౌ ళ్ళం","“బ” ఒత్తు, “ళ” ఒత్తు రెండూ ఉన్న పదం: కొబ్బరి నీళ్ళు.","జంట పదాలు: సబ్బు – బిళ్ళ, గొబ్బి – పాట, కాలి – జోళ్ళు."]},"qa":[["కాకి ఏమి ఎత్తుకెళ్ళింది?","సబ్బుబిళ్ళ."],["కాకి సబ్బుబిళ్ళ ఎందుకు తీసుకెళ్ళింది?","తన చంటిపిల్ల ఒళ్ళు రుద్దడానికి."],["సబ్బుతో రుద్దుకోవడం ఎందుకు?","మురికి పోవడానికి."],["క్రికెట్ ఆడినది ఎవరు?","రాజు."],["నీటిని పొదుపుగా ఎందుకు వాడాలి?","నీరు విలువైనది; వృథా చేస్తే భవిష్యత్తులో కొరత వస్తుంది."]],"act":"గేయాన్ని అభినయిస్తూ పాడండి. ఆధారాలతో కళ్ళజోడు బొమ్మ గీసి రంగులు వేయండి. పరిశుభ్రత, ఆరోగ్యం, చేతులు శుభ్రం చేసుకునే దశలు తెలుసుకోండి.","kn":"చేతులు కడుక్కునే దశలు: నీళ్ళతో తడపడం → సబ్బు రుద్దడం → అరచేతులు, వేళ్ళ మధ్య, గోళ్ళు, మణికట్టు శుభ్రం → నీళ్ళతో కడగడం → శుభ్రమైన గుడ్డతో తుడవడం. భోజనానికి ముందు, మరుగుదొడ్డి తర్వాత తప్పకుండా కడుక్కోవాలి.","qz":[["“సబ్బుబిళ్ళ” గేయ రచయిత","అలపర్తి వెంకట సుబ్బారావు","గురజాడ అప్పారావు","న్యాయపతి రాఘవరావు","జై సీతారాం"],["కాకి ఎత్తుకెళ్ళింది","సబ్బుబిళ్ళ","రొట్టెముక్క","పళ్ళెం","అద్దం"],["సబ్బు రుద్దగానే కాకిపిల్ల","మిలమిలా మెరిసింది","ఏడ్చింది","ఎగిరిపోయింది","నిద్రపోయింది"],["రుద్దుకొనుట ఎందుకు?","మురికి పోవడానికి","రంగు మారడానికి","వాసన కోసం","ఆట కోసం"],["క్రికెట్ ఆడినది","రాజు","అమ్మ","కళావతి","సుబ్బులు"],["క్రికెట్‌లో వాడిన బంతి","రబ్బరు బంతి","ప్లాస్టిక్ బంతి","కార్క్ బంతి","తోలు బంతి"],["అమ్మ కళావతితో పొదుపుగా వాడమన్నది","నీళ్ళు","సబ్బు","బట్టలు","డబ్బు"],["గడియ చిత్రానికి పదం","గొళ్ళెం","పళ్ళెం","కళ్ళెం","కిళ్ళీ"],["“బ” ఒత్తు, “ళ” ఒత్తు రెండూ ఉన్న పదం","కొబ్బరి నీళ్ళు","రుబ్బు రోలు","కొబ్బరికాయ","పళ్ళెం"],["చూపు సరిగా లేని వారికి అవసరం","కళ్ళజోడు","కాలి జోళ్ళు","గులాబి ముళ్ళు","పళ్ళెం"],["సుబ్బులు సంతలో కొన్నది","సబ్బుబిళ్ళ","కళ్ళజోడు","పళ్ళెం","చెప్పులు"],["అబ్బులు సంతలో కొన్నది","కళ్ళజోడు","సబ్బుబిళ్ళ","మబ్బు","నీళ్ళు"]],"tg":[["చిత్రం చూడండి (పుట 36)",["కుళాయి వద్ద బాలుడు సబ్బుతో స్నానం చేస్తున్నాడు; అమ్మ చెంబుతో నీళ్ళు పోస్తోంది; చెట్టుపై కాకి సబ్బుబిళ్ళ పట్టుకుంది; గూడులో కాకిపిల్లలు."]],["వినండి – మాట్లాడండి (పుట 37)",["ఆ) కాకి సబ్బుబిళ్ళ ఎత్తుకెళ్ళి తన పిల్ల ఒళ్ళు రుద్దింది; బాలుడు స్నానం చేస్తున్నాడు.","ఇ) స్నానానికి, చేతులు కడగడానికి, బట్టలు ఉతకడానికి, పాత్రలు తోమడానికి.","ఈ) 1. ఇ) రాజు  2. ఆ) రబ్బరు బంతి  3. ఇ) నీళ్ళు"]],["చదవండి (పుటలు 37–38)",["ఆ) గీత కింద గీయాల్సిన పంక్తులు గేయంలో: “ఒళ్ళు రుద్దనేమో ఆ సబ్బు బిళ్ళ”, “సబ్బు రుద్దగానే ఆ కాకి పిల్ల”, “కాకికీ ముద్దు కదా కాకి పిల్ల”; బ్బ, ళ్ళ ఒత్తులకు సున్నా.","ఈ) జతపరచడం: మబ్బు – మేఘం బొమ్మ, కొబ్బరికాయ – కొబ్బరి, కళ్ళు – కళ్ళ బొమ్మ, గొళ్ళెం – గడియ బొమ్మ.","ఊ) 1. సుబ్బులు, అబ్బులు – సంతకు వెళ్ళారు  2. సుబ్బులు – సబ్బుబిళ్ళ కొన్నది  3. అబ్బులు – కళ్ళజోడు కొన్నాడు  4. మబ్బులు కురిసాయి – నీళ్ళు చేరాయి"]],["రాయండి (పుట 39)",["బ్బ: బ్బ బ్బా బ్బి బ్బీ బ్బు బ్బూ బ్బృ బ్బె బ్బే బ్బై బ్బొ బ్బో బ్బౌ బ్బం","ళ్ళ: ళ్ళ ళ్ళా ళ్ళి ళ్ళీ ళ్ళు ళ్ళూ ళ్ళృ ళ్ళె ళ్ళే ళ్ళై ళ్ళొ ళ్ళో ళ్ళౌ ళ్ళం","ఆ) గళ్ళ పదాలు: కిళ్ళీ, కప్పు, సుబ్బులు, మజ్జిగ, కొబ్బరి, గబ్బిలం, బొజ్జ (ఉదా)"]],["నేనేమి నేర్చుకున్నాను? (పుట 40)",["1) ఆ) గొళ్ళెం  2) సబ్బుబిళ్ళ  3) ఆ) కొబ్బరి నీళ్ళు","4) సబ్బు – బిళ్ళ, గొబ్బి – పాట","5) ఆ) కళ్ళజోడు","6) చీకటిలో గబ్బిలాలు ఎగురుతాయి.","7) నీరు విలువైనది; అందరికీ సరిపోవాలి; వృథా చేస్తే కొరత వస్తుంది."]],["పద్య రత్నాలు, సూక్తులు (పుటలు 41–43)",["పద్యాలు: వెలుగు రాకముందె, బడికి వెళ్ళుటకును, అన్నిదానములను, కష్టపెట్టబోకు – రాగయుక్తంగా పాడించి భావం చెప్పాలి.","సూక్తులు: శ్రద్ధ ఉంటే ఓటమి ఉండదు • మంచి పనిని తక్షణం చేయాలి • ప్రార్థించే పెదవుల కన్నా సేవ చేసే చేతులే మిన్న • ద్వేషించే వారిని సైతం దీవించు • సోమరితనం పతనానికి దారి తీస్తుంది • ధర్మో రక్షతి రక్షితః • అణకువను మించిన భూషణం లేదు • మంచి పుస్తకాలే మంచి నేస్తాలు • పట్టుదలే అసలైన పెట్టుబడి • మంచి ఆరోగ్యం, తెలివి మనిషి జీవితంలో అందమైన వరాలు.","తెలుగు అంకెలు: ౧ ౨ ౩ ౪ ౫ ౬ ౭ ౮ ౯ ౧౦ … ౨౦"]]],"wb":{"pg":"37–41","f":"books/2/Class2_Workbook_Sem1.pdf","p":43,"ws":["చదవండి – పదాలు, చిత్రాలు, అక్షరాల గుర్తింపు","పదజాలం – గుణింతాలు, గళ్ళ పదాలు, జతపరచడం","రాయండి – పదాలు, వాక్యాలు, ఖాళీలు","సృజనాత్మకత / ఆలోచించి రాయండి"],"mis":"“బ” ఒత్తు (బ్బ), “ళ” ఒత్తు (ళ్ళ) – సబ్బుబిళ్ళ రెండూ ఉన్న పదం. ఒత్తు లేకపోతే అర్థం మారుతుంది.","qz":[["సుబ్బు ___ తాగాడు","కొబ్బరినీళ్ళు","గొళ్ళెం","జుబ్బా","సబ్బు"],["తాత ___ పెట్టుకున్నాడు","కళ్ళజోడు","జుబ్బా","సబ్బు","గొళ్ళెం"],["పాప రంగుల ___ వేసుకుంది","జుబ్బా","కళ్ళజోడు","గొళ్ళెం","సబ్బు"],["హారిక తలుపుకు ___ వేసింది","గొళ్ళెం","సబ్బు","జుబ్బా","కొబ్బరి"],["భోజనానికి ముందు ___ తో చేతులు కడగాలి","సబ్బు","కొబ్బరి","గొళ్ళెం","జుబ్బా"],["గ __ లం (గబ్బిలం)","బ్బి","ళ్ళి","ప్పి","జ్జి"],["ప __ (పళ్ళెం)","ళ్ళెం","బ్బెం","ప్పెం","జ్జెం"],["అబ్బులు ఏ నీళ్ళు తాగాడు?","కొబ్బరి నీళ్ళు","వేడి నీళ్ళు","మంచి నీళ్ళు","పాలు"],["“కడగాలి చేతులు సబ్బుతో” సరిచేస్తే","సబ్బుతో చేతులు కడగాలి","చేతులు కడగాలి సబ్బు","సబ్బు కడగాలి చేతులతో","కడగాలి సబ్బు చేతులు"],["ఆకారంలో చిన్నగా ఉంటాను, అందరి మురికి వదిలిస్తాను","సబ్బుబిళ్ళ","పళ్ళెం","దువ్వెన","చీపురు"],["చీకటిలో ఎగిరేవి","గబ్బిలాలు","పిచ్చుకలు","కోళ్ళు","చిలకలు"],["గుళ్ళో ___","పెళ్ళి","కళ్ళు","డబ్బులు","నీళ్ళు"]]}}],"eng":[{"id":"en1","no":1,"t":"1.1 Welcome to School","m":[8],"ty":"Rhyme & Activities","th":"School and Play","by":"Blossoms-2 English Reader – Unit 1: School and Play (pages 49–57)","sum":"Children recite the rhyme “Welcome to School” – boys and girls are welcomed to school, they say “hello” to friends, “Good morning” to teachers, learn and play and are good in every way. They greet each other (“Hi, Meera! How are you?” – “Hello, Raju! I am fine. Thank you.”), introduce themselves and friends (I am…, He is…, She is…), say “This is our school / classroom / playground”, learn names of things in a school bag and classroom, write names with capital letters (Devi), follow classroom instructions (Come here, Stand up, Sit down, Open your book) and practise short vowel sounds.","te":"“Welcome to School” గేయం – బడికి స్వాగతం, స్నేహితులకు hello, టీచర్‌కు Good morning, నేర్చుకో–ఆడుకో, అన్ని విధాలా మంచిగా ఉండు. పలకరింపులు, I am / He is / She is తో పరిచయం, This is our school/classroom/playground, బడి సంచిలో, తరగతిలో ఉండే వస్తువుల పేర్లు, పేర్లకు మొదటి అక్షరం capital, తరగతి సూచనలు (Come here, Sit down…), short vowel శబ్దాలు.","pts":["Rhyme: Welcome, welcome / Welcome to school, / Boys and girls, / Welcome to school. … With your friends / And say ‘hello’. … Meet your teachers / Say ‘Good morning’. … Learn and play / Be good in every way.","Sight words: to, in, be, and, your, say. New words: school, friends, meet, greet, learn, play, classroom, way.","Greetings: Hi, Meera! How are you? – Hello, Raju! I am fine. Thank you.","Introducing: I am Sarala. He is Raghu. He is my friend. I am Ramu. She is Shahin. She is my friend.","This is our school. This is our classroom. This is our playground.","School bag: a scale, an eraser, a slate, a book, a sharpener, a pencil, a pen, a water bottle. Classroom: a blackboard, a table, a chair, a window.","Names of people begin with a capital letter: devi → Devi.","Instructions: Come here. Stand up. Show me your pencil. Sit down. Pick up your bag. Open your book. Open the window."],"w":[["welcome","స్వాగతం"],["school","బడి"],["friend","స్నేహితుడు"],["teacher","ఉపాధ్యాయుడు"],["greet","పలకరించు"],["learn","నేర్చుకో"],["play","ఆడుకో"],["classroom","తరగతి గది"],["playground","ఆటస్థలం"],["slate","పలక"],["eraser","రబ్బరు"],["sharpener","చెక్కు సాధనం"]],"gr":{"t":"I am / He is / She is • This is our… • Capital letters for names","p":["I am Ramu. He is Raghu (boy). She is Shahin (girl).","This is our school. This is our classroom.","Names begin with capital letters: Devi, Anitha, Ravi.","a / an: a pencil, a book – an eraser (a, e, i, o, u శబ్దంతో మొదలైతే an).","Same ending sound: fan – man, cat – mat, pen – ten."]},"qa":[["What do we say to our teacher in the morning?","Good morning."],["What do we say to our friends?","Hello."],["How do you introduce your friend (a girl)?","She is ___. She is my friend."],["Name four things in your school bag.","Pencil, book, eraser, water bottle."],["Write your name correctly.","Begin with a capital letter, e.g. Devi."]],"act":"Recite “Welcome to School” with actions. Greet your friends in pairs and introduce yourself. Teacher gives instructions (Stand up, Sit down…) and children follow. Join the dots and colour the picture.","kn":"Proper nouns (names of people, places) always begin with a capital letter – Devi, Raju, Gudur.","qz":[["“Welcome to school, Boys and ___”","girls","teachers","friends","mothers"],["“Meet your teachers, Say ‘___’.”","Good morning","Good night","Bye","Hello"],["“With your friends and say ‘___’.”","hello","bye","sorry","thanks"],["“Learn and play, Be good in every ___”","way","day","school","time"],["Which is a school object?","Pencil","Spoon","Pillow","Plate"],["Which two words end with the same sound?","fan – man","bag – book","pen – box","cat – cup"],["Correct spelling","slate","stlae","satle","slaet"],["Correct way to write a name","Devi","devi","dEvi","DEVI"],["When your teacher enters in the morning, say","Good morning","Good night","Bye","Sorry"],["“___ is my friend.” (for a girl)","She","He","It","They"],["“This is our ___.” (place where we play)","playground","classroom","kitchen","bedroom"],["We use ___ eraser.","an","a","the","two"]],"wb":{"pg":"48–53","f":"books/2/Class2_Workbook_Sem1.pdf","p":54,"ws":["Activity 1–3: match pictures, What is this?, classroom / school bag things","Activity 4–5: capital letters, names with capitals","Activity 6–8: word families (-at, -en, -og, -ip, -un, -ap), word balloons, MCQs","Activity 9: copy writing"],"mis":"Names of people begin with a capital letter (giri → Giri). “pet – net” rhyme; “put” does not.","qz":[["Thing used for writing and carried in a school bag","a pencil","a scale","a chair","a window"],["“Gita put her pet in the net.” Same ending sound as “pet”","net","put","her","Gita"],["Ch _ _ r","a, i","i, a","e, i","o, a"],["Wrongly written name: Rahim, Suma, giri, John","giri","Rahim","Suma","John"],["c + at =","cat","cot","cut","act"],["d + og =","dog","dig","god","dug"],["h + en =","hen","him","pen","ten"],["Capital letter of “g”","G","Q","C","J"],["This is a ___. (book picture)","book","bag","bottle","pen"],["Found in a classroom","bench","pencil","eraser","water bottle"],["Found in a school bag","water bottle","window","blackboard","bench"],["s + un =","sun","son","sin","nus"]]},"tg":[["Let us Interact (page 49)",["1. A teacher and children (students).","2. They are at school / in front of the school.","3. Good morning, teacher / Namaste.","4. Hi! / Hello!","5. Happy and a little excited (own answer)."]],["Let us Speak (pages 51–52)",["A. Pair practice: Hi, ___! How are you? – Hello, ___! I am fine. Thank you.","B. I am ___. He/She is ___. He/She is my friend.","C. What is this? – This is our school / classroom / playground."]],["Let us Write (pages 54–55)",["A. Write your name and mother’s name with a capital first letter (e.g. Devi, Lakshmi).","B. Circle: scale, sharpener, books, eraser, water bottle (pencil, pen) – things we carry in a school bag.","C. book, pencil, slate (fill the missing letters)."]],["Let us Practise – Welcome to School (page 57)",["1. B) Pencil  2. B) fan – man  3. B) Good morning  4. C) slate","5. school  6. My name is Devi.","7. I am ___. This is my school. (own answer)"]]]},{"id":"en2","no":2,"t":"1.2 Games we play","m":[9],"ty":"Story & Activities","th":"School and Play","by":"Blossoms-2 English Reader – Unit 1: School and Play (pages 58–64)","sum":"It is play time. The teacher says, “Hi, children! It’s play time. Go and play some games.” Anu asks Abhi, Pooja and Ali, “Shall we play games?” Ali says, “We will play kabaddi.” Abhi agrees and they form two teams. Anu invites Ravi to join their team. All say, “Let’s start. It will be a great fun!” Children learn names of games (football, basketball, tennis, hockey, cricket, carrom, gilli danda, sack race, hide-and-seek, kho-kho, kabaddi), singular and plural with -s (ball – balls), long vowel sounds and make a paper flower.","te":"ఆటల సమయంలో టీచర్ పిల్లలను ఆడుకోమంటారు. అను “Shall we play games?” అని అడుగుతుంది; అలీ “We will play kabaddi” అంటాడు; రెండు జట్లు ఏర్పడతాయి; రవిని తమ జట్టులో చేరమంటారు. ఆటల పేర్లు, ఏకవచనం–బహువచనం (-s), దీర్ఘ అచ్చు శబ్దాలు, కాగితపు పువ్వు తయారీ.","pts":["Story: Teacher – “It’s play time. Go and play some games.” Children – “Thank you, teacher.” Anu – “Shall we play games?” Ali – “We will play kabaddi.” Abhi – “Let’s play kabaddi. We will form into two teams.” Anu – “Ravi, come and join our team.” Ravi – “Alright, I will join.” All – “Let’s start. It will be a great fun!”","Sight words: go, we, no, will, our. New words: form, team, join, great, fun.","Games: football, basketball, tennis, hockey, cricket, carrom, gilli danda, sack race, hide-and-seek, kabaddi, kho-kho.","Plural (more than one): add -s – ball → balls, bat → bats, ring → rings, shoe → shoes, coin → coins, rope → ropes, game → games.","Invite a friend: Shall we play? Come and join our team.","Paper flower: cut petals, glue around a small circle, attach to a straw stem, add leaves."],"w":[["game","ఆట"],["team","జట్టు"],["join","చేరు"],["form","ఏర్పరచు"],["great","గొప్ప"],["fun","సరదా"],["play time","ఆటల సమయం"],["shall we","మనం ___ దామా"],["sack race","గోనె సంచుల పరుగు"],["hide-and-seek","దాగుడుమూతలు"]],"gr":{"t":"Singular – Plural (-s) • Shall we…? / We will…","p":["One thing – singular: ball, bat, game. More than one – plural: balls, bats, games.","game → games, sport → sports, friend → friends, team → teams, teacher → teachers.","Shall we play games? – asking a friend politely. We will play kabaddi. – saying a plan.","Same ending sound: cab – lab, sea – me, man – fan."]},"qa":[["What did the teacher say?","Hi, children! It’s play time. Go and play some games."],["Which game did they decide to play?","Kabaddi."],["What did Anu ask Ravi?","Ravi, come and join our team."],["Which words show that the children are happy?","“Let’s start. It will be a great fun!”"],["Write the plural of “game”.","games"]],"act":"Role-play the dialogue in pairs with different games. Make a paper flower with colour paper, glue and a straw. Write your friends’ names and their favourite games.","kn":"Kabaddi and kho-kho are traditional Indian games. Playing games every day keeps us strong and happy.","qz":[["Which is a game?","Kabaddi","Pencil","Blackboard","Window"],["To invite a friend to play, say","Shall we play?","Go away","Sit down","Bye"],["Which game did the children decide to play?","Kabaddi","Cricket","Football","Kho-kho"],["Who said “We will play kabaddi”?","Ali","Anu","Abhi","Ravi"],["Whom did Anu ask to join the team?","Ravi","Ali","Pooja","Abhi"],["Into how many teams did they form?","Two","One","Three","Four"],["Plural of “game”","games","gamees","gamies","game"],["Plural of “shoe”","shoes","shoe","shoees","shos"],["Same ending sound","cab – lab","cab – cow","bee – bike","pen – pan"],["Game played with a bat and a ball","Cricket","Kho-kho","Carrom","Kabaddi"],["“It will be a great ___!”","fun","game","team","day"],["Game played on a board with coins","carrom","hockey","tennis","football"]],"wb":{"pg":"54–64","f":"books/2/Class2_Workbook_Sem1.pdf","p":60,"ws":["Activity 1–3: games words, fill in, friends’ favourite games","Activity 4–5: word grid, games and playthings","Activity 6–7: adding -s, word families (-ab, -ow, -ure, -ea, -ie, -ap)","Activity 8: rhyme & listening questions","Let us Practise (pages 61–63)"],"mis":"Plural of shoe is “shoes” (not shos/sheo). Names begin with a capital letter: Rajesh. Rhyming words have the same ending sound: sea – me.","qz":[["Same ending sound (sea, kite, me, bright)","sea – me","sea – kite","me – bright","kite – me"],["Correct spelling","cricket","criket","kriccet","crikket"],["books is for book, ___ is for shoe","shoes","sheo","shos","shoe"],["Ravi plays with a ball and a bat. Game?","Cricket","Kho-kho","Carrom","Kabaddi"],["Who is the boy in the story who likes games?","Kamal","Raju","Manju","Ravi"],["To become strong and happy like Kamal","Play games daily","Eat only sweets","Sleep in class","Watch TV"],["Right behaviour while playing in the park","Sharing and playing together","Shouting at friends","Pushing others","Fighting"],["Playing games everyday is a ___ habit","good","lazy","unhealthy","bad"],["Name written correctly","Rajesh","rajesH","raJesh","rajesh"],["Correct sentence (me / show / your / pencil)","Show me your pencil.","Pencil show me your.","Your pencil show me.","Me show pencil your."],["Same ending sound as “man”","fan","pet","sun","men"],["Who asks the children to go and play?","teacher","Anu","children","Ravi"]]},"tg":[["Let us Interact (page 58)",["1–2. Children are playing games in the playground (kho-kho, cricket, skipping, football…).","3. It is a holiday / Sunday (own answer).","4–5. Own answer – kabaddi, cricket, kho-kho."]],["Let us Read – questions (page 60)",["1. “Hi, children! It’s play time. Go and play some games.”  2. Kabaddi.","3. “Ravi, come and join our team.”  4. “Let’s start. It will be a great fun!”"]],["Let us Learn – plurals (page 61)",["ball – balls (done), bat – bats, ring – rings, shoe – shoes, coin – coins, rope – ropes (add -s only when the picture shows more than one)."]],["Let us Write (page 62)",["A. cricket (done), kabaddi, kho-kho, football, carrom, chess.","B. Pictures: cricket, football, kabaddi, kho-kho, basketball, tennis."]],["Let us Practise – Games we play (page 64)",["1. B) Kabaddi  2. B) Shall we play?  3. A) cab – lab","4. They are playing ___ (kabaddi/kho-kho – as in the picture).  5. games  6. We will play kabaddi."]]]},{"id":"en3","no":3,"t":"2.1 May I Help You?","m":[9],"ty":"Story & Activities","th":"Me and My House","by":"Blossoms-2 English Reader – Unit 2: Me and My House (pages 65–72)","sum":"One day, Madhav was walking to school. On the way, he met an old man. The old man wanted to cross the road. The road was busy with vehicles. Madhav asked the old man, “May I help you?” The old man replied, “Help me to cross the road, dear.” Madhav helped the old man to cross the road on the zebra lines. The old man blessed Madhav and went away. Madhav felt happy. Children learn to ask permission with “May I…?”, pronouns He, She, It, They, capital letters and full stop, and sentences with “It is…”.","te":"మాధవ్ బడికి వెళ్తుండగా రోడ్డు దాటాలనుకున్న ఒక వృద్ధుడిని చూశాడు. రోడ్డు వాహనాలతో రద్దీగా ఉంది. “May I help you?” అని అడిగి జీబ్రా గీతలపై రోడ్డు దాటించాడు. వృద్ధుడు ఆశీర్వదించాడు; మాధవ్ సంతోషించాడు. “May I…?” తో అనుమతి అడగడం, He/She/It/They సర్వనామాలు, capital letter, full stop, “It is…” వాక్యాలు.","pts":["Story: Madhav walking to school → met an old man who wanted to cross the busy road → “May I help you?” → “Help me to cross the road, dear.” → crossed on the zebra lines → the old man blessed him → Madhav felt happy.","New words: walk, wanted, cross, blessed, felt, replied.","Asking permission: May I take your pencil? – Yes, you may. May I go to the washroom? May I come in, madam/sir? May I play with you?","Pronouns are used in place of naming words: He (boy/man), She (girl/woman), It (thing/animal), They (more than one).","A sentence begins with a capital letter and ends with a full stop: i helped an old man → I helped an old man.","It is…: It is a book. It is a bus. It is a school. It is a bottle.","Help the needy – the blind, children, the physically challenged."],"w":[["help","సహాయం చేయు"],["old man","వృద్ధుడు"],["cross","దాటు"],["busy","రద్దీగా"],["vehicles","వాహనాలు"],["zebra lines","జీబ్రా గీతలు (రోడ్డు దాటే చోటు)"],["blessed","ఆశీర్వదించాడు"],["replied","జవాబిచ్చాడు"],["felt","అనిపించింది"],["may","అనుమతి అడిగే పదం"]],"gr":{"t":"May I…? • Pronouns He / She / It / They • Capital letter & full stop","p":["May I sit here? – Yes, you may.","Rani likes ice cream. She is eating an ice cream. Manu sings well. He is singing a song.","The lion is a wild animal. It lives in forests. Bunty and Chinni are brothers. They are sitting.","Start a sentence with a capital letter; end with a full stop (.).","Describing a thing: It is a road. It is a bus."]},"qa":[["Whom did Madhav meet on the way to school?","An old man."],["How was the road?","The road was busy with vehicles."],["What did Madhav ask the old man?","“May I help you?”"],["How did Madhav help the old man?","He helped him cross the road on the zebra lines."],["How did Madhav feel?","He felt happy."]],"act":"Practise “May I…?” dialogues in pairs. Role-play helping the blind, small kids and the physically challenged. Arrange story pictures in order.","kn":"Always cross the road on the zebra lines and look right–left–right. Helping others makes us happy.","qz":[["Who did Madhav help?","An old man","A dog","A child","A teacher"],["Why did the old man bless Madhav?","Madhav helped him cross the road","Madhav played with him","Madhav gave him food","Madhav sang a song"],["To sit beside your friend, say","May I sit here?","May I take your pencil?","Go away","Sit down"],["Pronoun for Bunty and Chinni","They","He","She","It"],["“Ramu likes sweets. ___ is eating sweets.”","He","She","It","They"],["“Rani likes ice cream. ___ is eating.”","She","He","It","They"],["Pronoun for a thing (a bus)","It","He","She","They"],["Where did Madhav help the old man cross?","On the zebra lines","Near a tree","At the bus stand","In the school"],["The road was busy with","vehicles","trees","children","animals"],["How did Madhav feel?","happy","sad","angry","tired"],["Correct sentence","I helped an old man.","i helped an old man","I helped an old man","i Helped an old man."],["Underline the pronoun: He is singing a song.","He","singing","song","is"]],"wb":{"pg":"65–70","f":"books/2/Class2_Workbook_Sem1.pdf","p":71,"ws":["Activity 1–2: match pictures, fill in (cross, blessed, happy)","Activity 3–4: He / She / They","Activity 5–6: capitals & full stop, “It is…” sentences","Activity 7–8: word families (-et, -an, -it, -ut, -ag, -ie, -ug, -at, -ot, -ub), MCQs","Activity 9: copy writing"],"mis":"Use “They” for two or more people (Raju and Ramu → They). A sentence begins with a capital letter, names too: The boy helped Madhavi.","qz":[["The old man wanted to ___ the road.","cross","happy","blessed","walk"],["The old man ___ Madhav and went away.","blessed","crossed","happy","walked"],["Madhav felt ___.","happy","cross","blessed","sad"],["“Ravi is a boy.” Change Ravi","He is a boy.","She is a boy.","They is a boy.","It is a boy."],["“Raju and Ramu are friends.” Change","They are friends.","He are friends.","She are friends.","It are friends."],["“Latha is a teacher.” Change","She is a teacher.","He is a teacher.","They is a teacher.","It is a teacher."],["Start a sentence describing a road","It is…","He is…","They are…","She is…"],["Polite way to ask permission","May I go to…","I go to…","Please go to…","Go to…"],["Correct sentence","The boy helped Madhavi.","the boy helped madhavi","The boy helped madhavi","the Boy helped Madhavi."],["___ is eating an ice-cream. (a girl)","She","It","The","They"],["p + et =","pet","pit","put","pat"],["c + at =","cat","cot","cut","cab"]]},"tg":[["Let us Interact (page 65)",["1. Two boys (and a teacher/parent) are in the picture.","2. The boy is crying because he fell down / got hurt.","3. The other boy is helping him get up.","4. Yes – I helped my friend who fell / my grandmother (own answer)."]],["Let us Read – questions (page 68)",["1. An old man.  2. The road was busy with vehicles.","3. “May I help you?”  4. He helped the old man to cross the road on the zebra lines."]],["Let us Write (page 70)",["B. 2. He met an old man.  3. The old man blessed Madhav.","C. 1. It is a book. 2. It is a bus. 3. It is a school. 4. It is a bottle."]],["Let us Practise – May I Help You? (page 72)",["1. B) An old man  2. B) Madhav helped him cross the road.  3. B) May I sit here?","4. C) They  5. Madhav  6. He is eating sweets.  7. He (He is singing a song.)"]]]},{"id":"en4","no":4,"t":"2.2 My House","m":[10],"ty":"Rhyme & Activities","th":"Me and My House","by":"Blossoms-2 English Reader – Unit 2: Me and My House (pages 73–81)","sum":"Children recite the rhyme “My Family” – Mother, will you walk with me? Father, will you talk to me? Brother, sister, will you jump with me? Grandmother, will you clap with me? Grandfather, will you smile with me? – “Yes, I will… We are a family!” Priya introduces her family: “He is my father. He is a driver. She is my mother. She is a fruit seller. I am Priya. I am 6 years old. I am studying class 2.” Children learn names of rooms and things in a house (window, bedroom, table, chair, stove, kitchen, roof, door, fan), the use of ’s for belonging (Priya’s house is beautiful), and the sounds of f and s.","te":"“My Family” గేయం – అమ్మ, నాన్న, అన్న–అక్క, నానమ్మ, తాతయ్యలతో నడవడం, మాట్లాడటం, గెంతడం, చప్పట్లు, నవ్వడం – “We are a family!”. ప్రియ తన కుటుంబాన్ని పరిచయం చేస్తుంది (నాన్న డ్రైవర్, అమ్మ పండ్లు అమ్ముతుంది). ఇంటిలోని గదులు, వస్తువులు, ’s తో ఎవరిదో చెప్పడం (Priya’s house), f, s శబ్దాలు.","pts":["Rhyme: Mother – walk with me; Father – talk to me; Brother, sister – jump with me; Grandmother – clap with me; Grandfather – smile with me. “Yes, I will, yes, I will, We are a family!”","Sight words: yes, are, me, will, smile.","Family members: father, mother, brother, sister, grandfather, grandmother.","Priya: He is my father. He is a driver. She is my mother. She is a fruit seller. I am Priya. I am 6 years old. I am studying class 2. This is my family.","House words: window, bedroom, table, chair, stove, brush, kitchen, roof, door, fan, garden.","’s shows belonging: Priya’s house, Gopi’s balloon, Mahi’s bag, the rabbit’s ears, cow’s milk.","Sounds: f – fox, fan, food, face • s – sun, sea, salt, sound."],"w":[["family","కుటుంబం"],["grandfather","తాతయ్య"],["grandmother","నానమ్మ / అమ్మమ్మ"],["driver","డ్రైవర్"],["fruit seller","పండ్లు అమ్మేవారు"],["house","ఇల్లు"],["kitchen","వంటగది"],["bedroom","పడకగది"],["roof","పైకప్పు"],["window","కిటికీ"],["stove","పొయ్యి"],["smile","నవ్వు"]],"gr":{"t":"’s (belonging) • He is / She is • Will you…? – Yes, I will.","p":["Add ’s to a naming word to show it belongs: Mahi’s bag is blue. We are going in our uncle’s car.","Latha is using her brother’s pen. The owl’s eyes are big. Cow’s milk is good for us.","He is my father. She is my mother.","Will you play with me? – Yes, I will. (polite reply)"]},"qa":[["What does Priya’s father do?","He is a driver."],["What does Priya’s mother do?","She is a fruit seller."],["How old is Priya?","Six years old."],["Which part of the house protects us from sun and rain?","The roof."],["Fill in: ___ bag is blue. (Mahi)","Mahi’s"]],"act":"Recite “My Family” with actions. Introduce your family like Priya. Draw your house and family tree. Say family names in your mother tongue.","kn":"A family with grandparents, parents and children living together is a joint family. In Telugu: grandfather – తాతయ్య, grandmother – నానమ్మ/అమ్మమ్మ.","qz":[["“Mother, mother, will you ___ with me?”","walk","talk","jump","clap"],["“Father, father, will you ___ to me?”","talk","walk","smile","jump"],["“Grandfather, will you ___ with me?”","smile","jump","clap","walk"],["“Yes, I will… We are a ___!”","family","school","team","house"],["Priya’s father is a","driver","teacher","farmer","doctor"],["Priya’s mother is a","fruit seller","teacher","driver","nurse"],["Not a family member","Friend","Mother","Father","Sister"],["Part of the house that protects us from sun and rain","Roof","Door","Window","Floor"],["Sentence that shows ownership","This is Ravi’s book.","This is Ravi book.","This Ravi book.","This is Ravis book."],["Polite reply to “Will you play with me?”","Yes, I will","No","Go away","Sit down"],["Same ending sound as “fan”","man","fat","fun","fin"],["Where do we cook food at home?","kitchen","bedroom","garden","store room"]],"wb":{"pg":"71–79","f":"books/2/Class2_Workbook_Sem1.pdf","p":77,"ws":["Activity 1–2: fill in (Priya’s family), match house words","Activity 3–4: ’s, brother / father / mother","Activity 5–6: word families (-at, -an, -ix, -ox, -un, -on, -it, -ad), Sruthi’s family","Activity 7–8: MCQs, listening (Reyansh)","Let us Practise; crossword puzzle"],"mis":"’s goes on the owner: The rabbit’s ears / The cow’s milk (not “cow milk’s”). “pot – cot” rhyme (same ending “-ot”), not “pot – pat”.","qz":[["Priya lives in a small ___.","town","garden","driver","vegetables"],["Her mother sells ___.","vegetables","town","garden","driver"],["This is ___ book. (Rani)","Rani’s","Ranis","Rani","Rani’"],["The ___ ears are big. (elephant)","elephant’s","elephants","elephant","elephants’s"],["Complete K_tch_n","i, e","e, i","a, i","i, a"],["Odd one out","sister","window","roof","door"],["Correct sentence","The rabbit’s ears are large.","The rabbit ears are large.","The rabbits ears are large.","The rabbit ears’ are large."],["Correctly spelt word","family","amlify","failmy","famly"],["Word to ask permission to enter the classroom","may","is","are","will"],["Correct use of ’s","The cow’s milk is good.","The cows milk is good.","The cow milk’s is good.","The cow milks is good."],["Same ending sound as “pot”","cot","cat","ten","pat"],["Raju sings well. ___ is singing a song.","He","She","It","They"]]},"tg":[["Let us Interact (page 73)",["1. Grandfather, grandmother, father, mother, brother and sister.","2. They are sitting together, talking and playing (as in the picture).","3–5. Own answers – I help my mother to clean the house…"]],["Let us Speak – questions (page 75)",["Own answers: family members, names of grandparents, number of members.","Mother tongue: Mother – అమ్మ, Father – నాన్న, Brother – అన్న/తమ్ముడు, Sister – అక్క/చెల్లి, Grandfather – తాతయ్య, Grandmother – నానమ్మ/అమ్మమ్మ."]],["Let us Learn – ’s (page 77)",["C. 1. Mahi’s bag is blue.  2. We are going in our uncle’s car.  3. Latha is using her brother’s pen.  4. The owl’s eyes are big.  5. Cow’s milk is good for us."]],["Let us Write (page 78)",["A. father, mother, driver, sister, house, garden.","B. roof, window, kitchen, door, fan, table."]],["Let us Practise – My House (page 81)",["1. A) Friend  2. B) Roof  3. B) This is Ravi’s book.  4. B) Yes, I will","5. man / can / pan  6. Grandfather, grandmother, father, mother, brother and sister."]]]}],"mat":[]};
